/** Local calendar date YYYY-MM-DD (avoids UTC shift from toISOString) */
function localYMD(d) {
  d = d || new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return y + '-' + m + '-' + day;
}


