/** Resolve client from select or manual name; create/update contact details. Returns client id or null. */
function resolveClientForSave(selectId, manualId, extrasPrefix) {
  const sel = document.getElementById(selectId);
  const man = document.getElementById(manualId);
  const selected = sel ? sel.value : '';
  const typed = (man ? man.value : '').trim();
  const extras = extrasPrefix ? readClientExtraFields(extrasPrefix) : {};

  if (selected) {
    const c = getClient(selected);
    if (c) {
      if (typed && typed !== c.name) c.name = typed;
      applyClientExtrasToRecord(c, extras);
    }
    return selected;
  }
  if (!typed) return null;
  const existing = (data.clients || []).find(c => (c.name || '').toLowerCase() === typed.toLowerCase());
  if (existing) {
    applyClientExtrasToRecord(existing, extras);
    if (sel) {
      const still = [...sel.options].some(o => o.value === existing.id);
      if (!still) {
        const opt = document.createElement('option');
        opt.value = existing.id;
        opt.textContent = existing.name;
        sel.appendChild(opt);
      }
      sel.value = existing.id;
    }
    return existing.id;
  }
  const id = uid();
  data.clients.push({
    id,
    name: typed,
    contact: extras.contact || '',
    phone: extras.phone || '',
    email: extras.email || '',
    address: extras.address || ''
  });
  logAudit('client_create', typed + ' (from document)');
  if (sel) {
    const opt = document.createElement('option');
    opt.value = id;
    opt.textContent = typed;
    sel.appendChild(opt);
    sel.value = id;
  }
  return id;
}

/** Ensure a product exists for a line item; create from name/price if needed. Returns productId. */
function ensureProductForLine(productId, name, unitNgn, addToInventory) {
  if (productId && getProduct(productId)) return productId;
  const n = (name || '').trim();
  if (!n) return productId || '';
  const existing = (data.products || []).find(p => (p.name || '').toLowerCase() === n.toLowerCase());
  if (existing) return existing.id;
  if (addToInventory === false) return productId || '';
  const id = uid();
  const sku = 'AUTO-' + Date.now().toString(36).slice(-6).toUpperCase();
  data.products.push({
    id,
    sku,
    name: n,
    description: '',
    category: '',
    brand: '',
    price: Number(unitNgn) || 0,
    currency: 'NGN',
    stock: 0,
    lowStock: 1,
    active: true
  });
  logAudit('product_create', n + ' (from document)');
  return id;
}


// -------------------- Persistence --------------------
function loadData() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      data = JSON.parse(raw);

      // Backfill timestamps so sort by newest/modified works
      (data.clients || []).forEach(function (c) {
        /* timestamps filled by ensureEntityTimestamps below */
      });
      (data.products || []).forEach(function (p) {
        /* timestamps filled by ensureEntityTimestamps below */
      });
      // Ensure structure
      if (!data.rates) data.rates = DEFAULT_DATA.rates;
      if (!data.rates.mode) data.rates.mode = 'manual';
      if (!data.company) data.company = DEFAULT_DATA.company;
      if (data.company && data.company.bankName === undefined) data.company.bankName = '';
      if (data.company && data.company.accountName === undefined) data.company.accountName = '';
      if (data.company && data.company.accountNumber === undefined) data.company.accountNumber = '';
      if (data.company && data.company.bankCode === undefined) data.company.bankCode = '';
      if (!data.products) data.products = [];
      if (!data.clients) data.clients = [];
      if (!data.quotes) data.quotes = [];
      if (!data.nextQuoteNum) data.nextQuoteNum = 1001;
      if (!data.categories || !Array.isArray(data.categories)) {
        // Seed from existing products + defaults
        const fromProducts = [...new Set(data.products.map(p => p.category).filter(Boolean))];
        data.categories = [...new Set([...(DEFAULT_DATA.categories || []), ...fromProducts])].sort();
      }
      if (!data.terms || !Array.isArray(data.terms) || data.terms.length === 0) {
        data.terms = JSON.parse(JSON.stringify(DEFAULT_DATA.terms));
      }
      if (!data.stockMovements || !Array.isArray(data.stockMovements)) {
        data.stockMovements = [];
      }
      if (!data.calendarEvents || !Array.isArray(data.calendarEvents)) data.calendarEvents = [];
      if (!data.invoices || !Array.isArray(data.invoices)) data.invoices = [];
      if (!data.nextInvoiceNum) data.nextInvoiceNum = 2001;
      if (!data.auditLog || !Array.isArray(data.auditLog)) data.auditLog = [];
      if (!data.noteTemplates || !Array.isArray(data.noteTemplates)) {
        data.noteTemplates = [
          { id: 't1', name: 'Payment terms (standard)', body: '70% mobilisation to commence, 10% on arrival at Nigerian cargo, 20% on delivery and installation.' },
          { id: 't2', name: 'Validity 30 days', body: 'This quotation is valid for 30 days from the date of issue and is subject to exchange-rate confirmation.' },
          { id: 't3', name: 'Warranty 12 months', body: '12 months manufacturer warranty from date of installation and commissioning.' }
        ];
      }
      if (!data.numbering) {
        data.numbering = {
          quotePrefix: 'MQ-',
          invoicePrefix: 'INV-',
          nextQuoteNum: data.nextQuoteNum || 1001,
          nextInvoiceNum: data.nextInvoiceNum || 2001
        };
      } else {
        if (data.numbering.nextQuoteNum == null) data.numbering.nextQuoteNum = data.nextQuoteNum || 1001;
        if (data.numbering.nextInvoiceNum == null) data.numbering.nextInvoiceNum = data.nextInvoiceNum || 2001;
      }
      if (!data.deviceProfile) {
        data.deviceProfile = { name: '', id: 'dev_' + Date.now().toString(36) };
      } else if (data.deviceProfile.name && /^this device$/i.test(String(data.deviceProfile.name).trim())) {
        data.deviceProfile.name = '';
      }
      if (!data.userProfile) data.userProfile = { username: '' };
      if (!Array.isArray(data.reportTableRows)) data.reportTableRows = [];
      if (!data.lastBackupAt) data.lastBackupAt = null;
      if (!data.settings) data.settings = {};
      if (data.settings.followUpDays == null) data.settings.followUpDays = 14;
      if (data.settings.autoDeductStockOnPaid == null) data.settings.autoDeductStockOnPaid = true;
      // Migrate invoices: payments array
      (data.invoices || []).forEach(inv => {
        if (!Array.isArray(inv.payments)) inv.payments = [];
        if (inv.amountPaid == null) {
          inv.amountPaid = (inv.payments || []).reduce((s, p) => s + (Number(p.amount) || 0), 0);
        }
        if (!inv.docType) inv.docType = 'tax';
        if (inv.stockDeducted == null) inv.stockDeducted = inv.status === 'paid';
      });
      (data.quotes || []).forEach(q => {
        if (q.followUpDone == null) q.followUpDone = false;
      });
      // Ensure every product has stock / lowStock numbers
      if (typeof ensureEntityTimestamps === 'function') {
        if (!data.deletedRecords || typeof data.deletedRecords !== 'object') data.deletedRecords = {};
        ensureEntityTimestamps(data.clients);
        ensureEntityTimestamps(data.products);
        ensureEntityTimestamps(data.quotes);
        ensureEntityTimestamps(data.invoices);
      }
      data.products.forEach(p => {
        if (typeof p.stock !== 'number' || isNaN(p.stock)) p.stock = 0;
        if (typeof p.lowStock !== 'number' || isNaN(p.lowStock)) p.lowStock = 1;
      });
    } else {
      data = JSON.parse(JSON.stringify(DEFAULT_DATA));
      saveData();
    }
  } catch (e) {
    console.error('Load error', e);
    data = JSON.parse(JSON.stringify(DEFAULT_DATA));
  }
  bindWindowData();
}

function saveDataLocalOnly() {
  try {
    if (data && typeof data === 'object') {
      data.updatedAt = data.updatedAt || new Date().toISOString();
    }
    bindWindowData();
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  } catch (e) {
    console.error('saveDataLocalOnly', e);
  }
}


/** Record a deletion so multi-device merge does not resurrect the item */
function markDeleted(id, kind) {
  if (!id) return;
  if (!data) return;
  if (!data.deletedRecords || typeof data.deletedRecords !== 'object') data.deletedRecords = {};
  data.deletedRecords[String(id)] = {
    at: new Date().toISOString(),
    kind: kind || 'record'
  };
}

function isMarkedDeleted(id) {
  if (!data || !data.deletedRecords || !id) return false;
  return !!data.deletedRecords[String(id)];
}


async function forceSyncCatalogNow() {
  const cloud = window.MedicanoCloud;
  if (!cloud || !cloud.pushNow) {
    alert('Cloud sync is not available. Sign in first.');
    return;
  }
  const info = cloud.getSyncInfo ? cloud.getSyncInfo() : {};
  if (!info.signedIn) {
    alert('Sign in as admin first.');
    return;
  }
  if (info.role && info.role !== 'admin') {
    alert('Only the admin can publish the full inventory to the team.');
    return;
  }
  try {
    const res = await (cloud.forcePublishCatalog ? cloud.forcePublishCatalog() : cloud.pushNow());
    if (res && res.ok) {
      alert('Published to the team.\n\nItems: ' + ((res.products != null) ? res.products : (data.products || []).length) +
        (res.chunks != null ? ('\nChunks: ' + res.chunks) : '') +
        '\n\nOther devices should refresh / reopen the app while signed into the same organisation.');
    } else {
      alert('Publish failed: ' + ((res && (res.reason || (res.error && res.error.message))) || 'unknown') +
        '\n\nIf this says permission/rules, add productChunks rules in Firebase Console.');
    }
  } catch (e) {
    alert('Publish error: ' + (e && e.message ? e.message : e));
  }
}

function saveData() {
  // Debounce disk write when catalog is large (import of 9k+ items)
  if ((data.products || []).length > 1500) {
    clearTimeout(window._saveDataTimer);
    window._saveDataTimer = setTimeout(function () { saveDataNow(); }, 400);
    clearTimeout(window._saveDataTimer);
    window._saveDataTimer = setTimeout(function () { saveDataNow(); }, 400);
    return;
  }
  return saveDataNow();
}
function saveDataNow() {
  if (data && typeof data === 'object') {
    data.updatedAt = new Date().toISOString();
  }
  bindWindowData();
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  if (window.MedicanoCloud && typeof window.MedicanoCloud.schedulePush === 'function') {
    window.MedicanoCloud.schedulePush();
  }
}

function refreshAllViews() {
  try {
    const page = document.querySelector('.page:not(.hidden)');
    const id = page && page.id ? page.id.replace('page-', '') : 'dashboard';
    if (typeof navigate === 'function') navigate(id === 'quote-editor' ? 'quotes' : id === 'invoice-editor' ? 'invoices' : id === 'client-detail' ? 'clients' : id);
  } catch (e) {
    if (typeof renderDashboard === 'function') renderDashboard();
  }
}

// ---- Auth UI (Firebase bridge) ----
let authMode = 'signin';


function showForgotPassword() {
  const form = document.getElementById('auth-form');
  const forgot = document.getElementById('auth-forgot-panel');
  const tabs = document.querySelector('.auth-tabs');
  const help = document.getElementById('auth-modal-help');
  const title = document.getElementById('auth-modal-title');
  if (form) form.classList.add('hidden');
  if (tabs) tabs.classList.add('hidden');
  if (forgot) forgot.classList.remove('hidden');
  if (title) title.textContent = 'Reset password';
  if (help) help.textContent = 'Enter your account email. Firebase will send a reset link if the account exists.';
  const err = document.getElementById('auth-error');
  if (err) { err.textContent = ''; err.classList.add('hidden'); }
  const email = document.getElementById('auth-email')?.value || '';
  const fe = document.getElementById('auth-forgot-email');
  if (fe && email) fe.value = email;
}

function hideForgotPassword() {
  const form = document.getElementById('auth-form');
  const forgot = document.getElementById('auth-forgot-panel');
  const tabs = document.querySelector('.auth-tabs');
  const help = document.getElementById('auth-modal-help');
  if (form) form.classList.remove('hidden');
  if (tabs) tabs.classList.remove('hidden');
  if (forgot) forgot.classList.add('hidden');
  setAuthMode(authMode || 'signin');
  if (help) help.textContent = 'Sign in to sync Medicano across your devices via Firebase.';
}

async function sendForgotPassword(ev) {
  if (ev) ev.preventDefault();
  const email = (document.getElementById('auth-forgot-email')?.value || '').trim();
  const err = document.getElementById('auth-forgot-error');
  const ok = document.getElementById('auth-forgot-success');
  if (err) { err.textContent = ''; err.classList.add('hidden'); }
  if (ok) { ok.textContent = ''; ok.classList.add('hidden'); }
  if (!email) {
    if (err) { err.textContent = 'Enter your email address.'; err.classList.remove('hidden'); }
    return;
  }
  const cloud = window.MedicanoCloud;
  if (!cloud || !cloud.resetPassword) {
    if (err) { err.textContent = 'Cloud auth is not available.'; err.classList.remove('hidden'); }
    return;
  }
  try {
    await cloud.resetPassword(email);
    if (ok) {
      ok.textContent = 'If an account exists for this email, a password reset link has been sent. Check your inbox (and spam).';
      ok.classList.remove('hidden');
    }
  } catch (e) {
    let msg = (e && e.message) ? e.message : String(e);
    if (/user-not-found/i.test(msg)) msg = 'If an account exists for this email, a reset link has been sent.';
    if (/invalid-email/i.test(msg)) msg = 'That email address is not valid.';
    if (/network/i.test(msg)) msg = 'Network error. Check your connection and try again.';
    // Always show generic success-style for enumeration safety when user-not-found
    if (/user-not-found/i.test(String(e && e.code))) {
      if (ok) {
        ok.textContent = 'If an account exists for this email, a password reset link has been sent. Check your inbox (and spam).';
        ok.classList.remove('hidden');
      }
      return;
    }
    if (err) { err.textContent = msg; err.classList.remove('hidden'); }
  }
}

function openAuthModal() {
  const m = document.getElementById('auth-modal');
  if (!m) return;
  m.classList.remove('hidden');
  const forgot = document.getElementById('auth-forgot-panel');
  if (forgot) forgot.classList.add('hidden');
  const form = document.getElementById('auth-form');
  if (form) form.classList.remove('hidden');
  const tabs = document.querySelector('.auth-tabs');
  if (tabs) tabs.classList.remove('hidden');
  const cloud = window.MedicanoCloud;
  const hint = document.getElementById('auth-config-hint');
  if (hint) {
    if (cloud && cloud.isConfigured && cloud.isConfigured()) hint.classList.add('hidden');
    else hint.classList.remove('hidden');
  }
  setAuthMode(authMode);
}

function closeAuthModal() {
  const m = document.getElementById('auth-modal');
  if (m) m.classList.add('hidden');
  const err = document.getElementById('auth-error');
  if (err) { err.textContent = ''; err.classList.add('hidden'); }
}

function setAuthMode(mode) {
  authMode = mode === 'signup' ? 'signup' : 'signin';
  const title = document.getElementById('auth-modal-title');
  const submit = document.getElementById('auth-submit');
  const tabIn = document.getElementById('auth-tab-signin');
  const tabUp = document.getElementById('auth-tab-signup');
  if (title) title.textContent = authMode === 'signup' ? 'Create account' : 'Sign in';
  if (submit) submit.textContent = authMode === 'signup' ? 'Create account' : 'Sign in';
  if (tabIn) tabIn.classList.toggle('is-active', authMode === 'signin');
  if (tabUp) tabUp.classList.toggle('is-active', authMode === 'signup');
  if (tabIn) tabIn.classList.toggle('soft', authMode !== 'signin');
  if (tabUp) tabUp.classList.toggle('soft', authMode !== 'signup');
}

async function submitAuthForm(e) {
  e.preventDefault();
  const email = (document.getElementById('auth-email')?.value || '').trim();
  const password = document.getElementById('auth-password')?.value || '';
  const err = document.getElementById('auth-error');
  const cloud = window.MedicanoCloud;
  if (!cloud) {
    if (err) {
      err.textContent = 'Cloud module not loaded. Hard-refresh the page (or update the app). You need a network connection the first time to load Firebase.';
      err.classList.remove('hidden');
    }
    return;
  }
  if (cloud.isConfigured && !cloud.isConfigured()) {
    if (err) {
      err.textContent = 'Firebase is not configured or the SDK failed to load. Check firebase-config.js and your network.';
      err.classList.remove('hidden');
    }
    return;
  }
  try {
    if (authMode === 'signup') await cloud.signUp(email, password);
    else await cloud.signIn(email, password);
    closeAuthModal();
    if (typeof logAudit === 'function') logAudit('auth', authMode + ' ' + email);
  } catch (ex) {
    if (err) {
      err.textContent = (ex && ex.message) ? ex.message : String(ex);
      err.classList.remove('hidden');
    }
  }
}

async function onAuthActionClick() {
  const cloud = window.MedicanoCloud;
  if (cloud && cloud.isSignedIn && cloud.isSignedIn()) {
    if (confirm('Sign out? Data stays on this device; cloud sync pauses until you sign in again.')) {
      await cloud.signOut();
    }
    return;
  }
  openAuthModal();
}

async function manualCloudSync() {
  const cloud = window.MedicanoCloud;
  if (!cloud || !cloud.isSignedIn || !cloud.isSignedIn()) {
    openAuthModal();
    return;
  }
  if (typeof cloud.syncNow === 'function') {
    const r = await cloud.syncNow();
    if (r && r.ok) {
      refreshAllViews();
      const nClients = (data.clients || []).length;
      const nInv = (data.invoices || []).length;
      alert('Sync complete.' + String.fromCharCode(10) + 'Clients: ' + nClients + String.fromCharCode(10) + 'Invoices: ' + nInv);
    } else {
      alert('Sync failed. Check Firestore rules and that you are online.');
    }
  }
}

