// -------------------- Helpers --------------------
function formatNGN(amount) {
  return '₦' + Number(amount || 0).toLocaleString('en-NG', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function formatMoney(amount, currency) {
  if (currency === 'NGN') return formatNGN(amount);
  return (currency === 'EUR' ? '€' : '$') + Number(amount || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function toNGN(price, currency) {
  if (currency === 'NGN') return Number(price);
  const rate = data.rates[currency] || 1;
  return Number(price) * rate;
}

function uid() {
  return 'id_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}


function getProduct(id) {
  return (data.products || []).find(p => p.id === id);
}

/** Variants on a product (size, colour, dimension, etc.) */
function productVariants(p) {
  if (!p || !Array.isArray(p.variants)) return [];
  return p.variants.filter(function (v) { return v && (v.label || v.sku); });
}

function getVariant(productId, variantId) {
  const p = getProduct(productId);
  if (!p || !variantId) return null;
  return productVariants(p).find(function (v) { return v.id === variantId; }) || null;
}

function variantDisplayName(p, v) {
  const base = (p && p.name) || 'Item';
  if (!v) return base;
  const lab = (v.label || v.sku || '').trim();
  return lab ? (base + ' — ' + lab) : base;
}

function variantUnitPrice(p, v) {
  if (v && v.price != null && v.price !== '') {
    return { price: Number(v.price) || 0, currency: v.currency || (p && p.currency) || 'NGN' };
  }
  return { price: Number(p && p.price) || 0, currency: (p && p.currency) || 'NGN' };
}

