function collectInvoiceItems() {
  const items = [];
  document.querySelectorAll('#invoice-items-list .line-card').forEach(tr => {
    const productId = tr.querySelector('.inv-product')?.value || '';
    const variantId = tr.querySelector('.inv-variant')?.value || '';
    const name = tr.querySelector('.inv-name')?.value.trim() || '';
    const qty = parseFloat(tr.querySelector('.inv-qty')?.value) || 0;
    const unitNgn = parseFloat(tr.querySelector('.inv-unit')?.value) || 0;
    if (!name && !productId) return;
    const p = getProduct(productId);
    const v = variantId ? getVariant(productId, variantId) : null;
    items.push({
      productId,
      variantId: variantId || undefined,
      name: name || (typeof variantDisplayName === 'function' ? variantDisplayName(p, v) : ((p && p.name) || 'Item')),
      qty, unitNgn, lineNgn: qty * unitNgn
    });
  });
  return items;
}


/** Bidirectional discount: % ↔ amount. Mode tracks which field the user last edited. */
function getLineSubtotal(kind) {
  kind = kind || 'invoice';
  let sub = 0;
  if (kind === 'quote') {
    document.querySelectorAll('#quote-items-list .line-card, #quote-items-list tr').forEach(function (row) {
      const qty = parseFloat(row.querySelector('.qi-qty')?.value) || 0;
      const base = parseFloat(row.querySelector('.qi-base')?.value) || 0;
      const markup = parseFloat(row.querySelector('.qi-markup')?.value) || 0;
      const unit = base * (1 + markup / 100);
      // prefer displayed line total if present
      const lineEl = row.querySelector('.qi-line, .qi-line-body');
      if (lineEl && lineEl.textContent) {
        const n = parseFloat(String(lineEl.textContent).replace(/[^\d.-]/g, ''));
        if (!isNaN(n) && n > 0) { sub += n; return; }
      }
      sub += qty * unit;
    });
  } else {
    document.querySelectorAll('#invoice-items-list .line-card').forEach(function (tr) {
      const qty = parseFloat(tr.querySelector('.inv-qty')?.value) || 0;
      const unit = parseFloat(tr.querySelector('.inv-unit')?.value) || 0;
      sub += qty * unit;
    });
  }
  return sub;
}

function resolveDiscount(kind, subtotal) {
  kind = kind || 'invoice';
  window._discountMode = window._discountMode || {};
  const mode = window._discountMode[kind] || 'pct';
  const pctEl = document.getElementById(kind === 'quote' ? 'quote-discount' : 'inv-discount');
  const amtEl = document.getElementById(kind === 'quote' ? 'quote-discount-amt' : 'inv-discount-amt');
  let pct = parseFloat(pctEl && pctEl.value) || 0;
  let amt = parseFloat(amtEl && amtEl.value) || 0;
  subtotal = Number(subtotal) || 0;
  if (mode === 'amt') {
    amt = Math.max(0, Math.min(amt, subtotal));
    pct = subtotal > 0 ? (amt / subtotal) * 100 : 0;
  } else {
    pct = Math.max(0, Math.min(pct, 100));
    amt = subtotal * (pct / 100);
  }
  const total = Math.max(0, subtotal - amt);
  return { pct: pct, amt: amt, total: total, mode: mode };
}

function onDiscountPctInput(kind) {
  window._discountMode = window._discountMode || {};
  window._discountMode[kind] = 'pct';
  const sub = getLineSubtotal(kind);
  const disc = resolveDiscount(kind, sub);
  const amtEl = document.getElementById(kind === 'quote' ? 'quote-discount-amt' : 'inv-discount-amt');
  if (amtEl) {
    // Show rounded amount without fighting the user typing %
    amtEl.value = disc.amt ? (Math.round(disc.amt * 100) / 100) : 0;
  }
  if (kind === 'quote') {
    if (typeof recalcQuoteTotal === 'function') recalcQuoteTotal();
  } else {
    recalcInvoiceTotal();
  }
}

function onDiscountAmtInput(kind) {
  window._discountMode = window._discountMode || {};
  window._discountMode[kind] = 'amt';
  const sub = getLineSubtotal(kind);
  const disc = resolveDiscount(kind, sub);
  const pctEl = document.getElementById(kind === 'quote' ? 'quote-discount' : 'inv-discount');
  if (pctEl) {
    // Approximate % for display; amount drives the total
    pctEl.value = disc.pct ? (Math.round(disc.pct * 100) / 100) : 0;
  }
  if (kind === 'quote') {
    if (typeof recalcQuoteTotal === 'function') recalcQuoteTotal();
  } else {
    recalcInvoiceTotal();
  }
}

function recalcInvoiceTotal() {
  let sub = 0;
  document.querySelectorAll('#invoice-items-list .line-card').forEach(tr => {
    const qty = parseFloat(tr.querySelector('.inv-qty')?.value) || 0;
    const unit = parseFloat(tr.querySelector('.inv-unit')?.value) || 0;
    const line = qty * unit;
    sub += line;
    const lineStr = formatNGN(line);
    tr.querySelectorAll('.inv-line, .inv-line-body').forEach(cell => { cell.textContent = lineStr; });
  });
  const disc = resolveDiscount('invoice', sub);
  // Keep the passive field in sync without changing mode
  const mode = (window._discountMode && window._discountMode.invoice) || 'pct';
  if (mode === 'pct') {
    const amtEl = document.getElementById('inv-discount-amt');
    if (amtEl && document.activeElement !== amtEl) amtEl.value = disc.amt ? (Math.round(disc.amt * 100) / 100) : 0;
  } else {
    const pctEl = document.getElementById('inv-discount');
    if (pctEl && document.activeElement !== pctEl) pctEl.value = disc.pct ? (Math.round(disc.pct * 100) / 100) : 0;
  }
  const s = document.getElementById('inv-subtotal');
  const t = document.getElementById('inv-total');
  if (s) s.textContent = formatNGN(sub);
  if (t) t.textContent = formatNGN(disc.total);
  return { sub, total: disc.total, discount: disc.pct, discountAmount: disc.amt };
}


/** Display name for invoice document type (PDF + lists + default title) */
function invoiceDocLabel(inv) {
  inv = inv || {};
  const status = String(inv.status || '').toLowerCase();
  const docType = String(inv.docType || 'tax').toLowerCase();
  // Payment status wins for naming
  if (status === 'paid') return 'Receipt';
  if (status === 'partial') return 'Partial Invoice';
  if (docType === 'proforma' || docType === 'pro forma') return 'Proforma Invoice';
  if (status === 'draft') return 'Draft Invoice';
  return 'Invoice';
}

/** Always derive the document name from type + status when saving */
function invoiceAutoTitle(inv) {
  return invoiceDocLabel(inv || {});
}

function isGenericInvoiceTitle(title) {
  const t = String(title || '').trim().toLowerCase();
  if (!t) return true;
  return /^(invoice|draft invoice|proforma invoice|pro forma invoice|receipt|partial invoice|new invoice|tax invoice)$/i.test(t);
}

function saveInvoice() {
  try {
  const clientId = resolveClientForSave('inv-client', 'inv-client-manual', 'inv-client');
  if (!clientId) { alert('Please select or type a client name.'); return; }
  // Ensure products for custom lines before collect
  const addInvItems = document.getElementById('inv-add-to-inventory')?.checked !== false;
  document.querySelectorAll('#invoice-items-list .line-card').forEach(tr => {
    let productId = tr.querySelector('.inv-product')?.value || '';
    const name = tr.querySelector('.inv-name')?.value.trim() || '';
    const unitNgn = parseFloat(tr.querySelector('.inv-unit')?.value) || 0;
    productId = ensureProductForLine(productId, name, unitNgn, addInvItems);
    const sel = tr.querySelector('.inv-product');
    if (sel && productId) {
      // Works for both <select> and searchable picker hidden input
      if (sel.tagName === 'SELECT' && sel.options) {
        if (![...sel.options].some(o => o.value === productId)) {
          const opt = document.createElement('option');
          opt.value = productId;
          opt.textContent = name || (getProduct(productId) || {}).name || 'Item';
          sel.appendChild(opt);
        }
      }
      sel.value = productId;
      const pickerInput = tr.querySelector('.product-picker-input');
      if (pickerInput) {
        const p = getProduct(productId);
        pickerInput.value = p ? ((p.sku ? p.sku + ' · ' : '') + (p.name || name || '')) : (name || productId);
      }
    }
  });
  const items = collectInvoiceItems();
  if (!items.length) { alert('Add at least one line item.'); return; }
  const totals = recalcInvoiceTotal();
  const sub = totals.sub;
  const disc = resolveDiscount('invoice', sub);
  const statusVal = (document.getElementById('inv-status')?.value || 'draft').trim() || 'draft';
  const docTypeVal = document.getElementById('inv-doc-type')?.value || 'tax';
  // Document name always follows type + status (Proforma / Receipt / Partial / Invoice)
  const autoLabel = invoiceAutoTitle({ status: statusVal, docType: docTypeVal });
  let titleVal = autoLabel;
  const titleEl = document.getElementById('inv-title');
  if (titleEl) titleEl.value = titleVal;
  const payload = {
    clientId,
    title: titleVal,
    status: statusVal,
    date: document.getElementById('inv-date')?.value || new Date().toISOString().slice(0, 10),
    dueDate: document.getElementById('inv-due')?.value || '',
    quoteRef: document.getElementById('inv-quote-ref')?.value.trim() || '',
    notes: document.getElementById('inv-notes')?.value.trim() || '',
    showFooter: document.getElementById('inv-show-footer')?.checked !== false,
    showItemDescriptions: document.getElementById('inv-show-descriptions')?.checked !== false,
    discount: disc.pct,
    discountAmount: disc.amt,
    discountMode: (window._discountMode && window._discountMode.invoice) || 'pct',
    items,
    subtotalNgn: sub,
    totalNgn: disc.total,
    updatedAt: new Date().toISOString()
  };
  payload.bankName = (document.getElementById('inv-bank-name')?.value || '').trim();
  payload.accountName = (document.getElementById('inv-account-name')?.value || '').trim();
  payload.accountNumber = (document.getElementById('inv-account-number')?.value || '').trim();
  payload.bankCode = (document.getElementById('inv-bank-code')?.value || '').trim();
  payload.docType = docTypeVal;
  if (!data.invoices) data.invoices = [];
  if (currentInvoiceId) {
    const idx = data.invoices.findIndex(x => x.id === currentInvoiceId);
    if (idx >= 0) {
      const prev = data.invoices[idx];
      data.invoices[idx] = {
        ...prev,
        ...payload,
        payments: prev.payments || [],
        amountPaid: prev.amountPaid || 0,
        stockDeducted: prev.stockDeducted || false
      };
      refreshInvoicePaymentStatus(data.invoices[idx], { silent: true });
    }
  } else {
    currentInvoiceId = 'inv' + Date.now();
    const invNum = nextInvoiceNumber();
    const inv = {
      id: currentInvoiceId,
      invoiceNumber: invNum,
      createdAt: new Date().toISOString(),
      payments: [],
      amountPaid: 0,
      stockDeducted: false,
      ...payload
    };
    refreshInvoicePaymentStatus(inv, { silent: true });
    data.invoices.push(inv);
    document.getElementById('invoice-editor-title').textContent = invoiceDocLabel(inv) + ' ' + invNum;
    document.getElementById('btn-delete-invoice')?.classList.remove('hidden');
  }
  if (typeof saveDataNow === 'function') saveDataNow();
  else saveData();
  logAudit('invoice_save', (data.invoices.find(x => x.id === currentInvoiceId) || {}).invoiceNumber || '');
  if (window.MedicanoCloud && typeof window.MedicanoCloud.pushNow === 'function') {
    window.MedicanoCloud.pushNow().catch(function (e) { console.warn('invoice push', e); });
  }
  const savedInv = (data.invoices || []).find(x => x.id === currentInvoiceId);
  if (savedInv) {
    const st = document.getElementById('inv-status');
    if (st) st.value = savedInv.status || 'draft';
    const title = document.getElementById('invoice-editor-title');
    if (title) title.textContent = invoiceDocLabel(savedInv) + ' ' + (savedInv.invoiceNumber || '');
  }
  if (typeof renderInvoices === 'function') renderInvoices();
  renderInvoicePaymentsPanel();
  if (typeof renderClients === 'function') renderClients();
  if (typeof renderProducts === 'function') renderProducts();
  alert('Invoice saved' + (statusVal ? (' · Status: ' + statusVal) : '') + '.');
  } catch (err) {
    console.error('saveInvoice', err);
    alert('Could not save invoice: ' + (err && err.message ? err.message : err));
  }
}

