/** Invoice PDF — jsPDF file download (same method as Client Presentation) */
function wrapPdfLines(doc, text, maxWidth) {
  const maxW = Math.max(20, Number(maxWidth) || 20);
  const paragraphs = String(text == null ? '' : text).split(/\r?\n/);
  const lines = [];
  paragraphs.forEach(function (para) {
    if (!para) { lines.push(''); return; }
    const words = String(para).split(/(\s+)/);
    let cur = '';
    words.forEach(function (piece) {
      if (!piece) return;
      const test = cur + piece;
      if (doc.getTextWidth(test) <= maxW) { cur = test; return; }
      if (cur) lines.push(cur.replace(/\s+$/, ''));
      if (doc.getTextWidth(piece) <= maxW) { cur = piece.replace(/^\s+/, ''); return; }
      let chunk = '';
      for (let i = 0; i < piece.length; i++) {
        const next = chunk + piece[i];
        if (doc.getTextWidth(next) <= maxW) chunk = next;
        else { if (chunk) lines.push(chunk); chunk = piece[i]; }
      }
      cur = chunk;
    });
    if (cur) lines.push(cur.replace(/\s+$/, ''));
  });
  return lines.length ? lines : [''];
}


// -------------------- Receivables: statement + ageing --------------------
function parseYmd(s) {
  if (!s) return null;
  const d = new Date(String(s).slice(0, 10) + 'T12:00:00');
  return isNaN(d.getTime()) ? null : d;
}

function daysBetween(a, b) {
  const ms = b.getTime() - a.getTime();
  return Math.floor(ms / 86400000);
}

function ageingBucket(days) {
  if (days <= 30) return '0-30';
  if (days <= 60) return '31-60';
  if (days <= 90) return '61-90';
  return '90+';
}

/** Statement lines for one client in optional date range */
function buildClientStatementLines(clientId, fromStr, toStr) {
  const from = parseYmd(fromStr);
  const to = parseYmd(toStr);
  const lines = [];
  (data.invoices || []).filter(function (inv) {
    return inv.clientId === clientId && inv.status !== 'cancelled';
  }).forEach(function (inv) {
    const invDate = (inv.date || inv.createdAt || '').slice(0, 10);
    const d = parseYmd(invDate) || new Date();
    if (from && d < from) return;
    if (to && d > to) return;
    const total = Number(inv.totalNgn != null ? inv.totalNgn : inv.totalNGN) || 0;
    lines.push({
      date: invDate,
      sort: d.getTime(),
      type: 'invoice',
      ref: inv.invoiceNumber || inv.id,
      description: inv.title || 'Invoice',
      debit: total,
      credit: 0,
      invId: inv.id
    });
    (inv.payments || []).forEach(function (p) {
      const pd = (p.date || '').slice(0, 10);
      const pdd = parseYmd(pd) || d;
      if (from && pdd < from) return;
      if (to && pdd > to) return;
      lines.push({
        date: pd || invDate,
        sort: pdd.getTime() + 1,
        type: 'payment',
        ref: inv.invoiceNumber || inv.id,
        description: (p.method || 'Payment') + (p.note ? (' — ' + p.note) : ''),
        debit: 0,
        credit: Number(p.amount) || 0,
        invId: inv.id
      });
    });
    // If paid via amountPaid without payment lines, synthesise credit
    if (!(inv.payments || []).length) {
      const paid = Number(inv.amountPaid) || 0;
      if (paid > 0) {
        lines.push({
          date: invDate,
          sort: d.getTime() + 1,
          type: 'payment',
          ref: inv.invoiceNumber || inv.id,
          description: 'Payment recorded',
          debit: 0,
          credit: paid,
          invId: inv.id
        });
      }
    }
  });
  lines.sort(function (a, b) { return a.sort - b.sort; });
  let bal = 0;
  lines.forEach(function (ln) {
    bal += (ln.debit || 0) - (ln.credit || 0);
    ln.balance = bal;
  });
  return lines;
}

function buildAgeingRows(asOfStr) {
  const asOf = parseYmd(asOfStr) || new Date();
  const byClient = {};
  (data.invoices || []).forEach(function (inv) {
    if (!inv || inv.status === 'cancelled' || inv.status === 'draft') return;
    const bal = typeof invoiceBalance === 'function' ? invoiceBalance(inv) : 0;
    if (bal <= 0.009) return;
    const invDate = parseYmd((inv.date || inv.createdAt || '').slice(0, 10)) || asOf;
    const days = Math.max(0, daysBetween(invDate, asOf));
    const bucket = ageingBucket(days);
    const cid = inv.clientId || '_none';
    if (!byClient[cid]) {
      const c = getClient(cid);
      byClient[cid] = {
        clientId: cid,
        name: c ? c.name : '(No client)',
        '0-30': 0, '31-60': 0, '61-90': 0, '90+': 0,
        total: 0
      };
    }
    byClient[cid][bucket] += bal;
    byClient[cid].total += bal;
  });
  return Object.values(byClient).sort(function (a, b) {
    return (b.total - a.total) || a.name.localeCompare(b.name);
  });
}

