function generateClientStatementPdf() {
  const clientId = document.getElementById('recv-client')?.value || '';
  if (!clientId) { alert('Select a client first.'); return; }
  const c = getClient(clientId);
  if (!c) { alert('Client not found.'); return; }
  const from = document.getElementById('recv-from')?.value || '';
  const to = document.getElementById('recv-to')?.value || '';
  const lines = buildClientStatementLines(clientId, from, to);
  const co = data.company || {};
  loadJsPdf().then(function (JsPDF) {
    const doc = new JsPDF({ unit: 'pt', format: 'a4' });
    const W = doc.internal.pageSize.getWidth();
    const M = 42;
    let y = 48;
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(16);
    doc.setTextColor(15, 118, 110);
    doc.text(co.name || 'Medicano Resources Limited', M, y);
    y += 22;
    doc.setFontSize(14);
    doc.setTextColor(30, 41, 59);
    doc.text('Statement of Account', M, y);
    y += 18;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
    doc.setTextColor(100, 116, 139);
    doc.text('Client: ' + (c.name || ''), M, y); y += 14;
    if (c.contact) { doc.text('Attn: ' + c.contact, M, y); y += 12; }
    const period = (from || '…') + '  →  ' + (to || 'today');
    doc.text('Period: ' + period, M, y); y += 18;
    doc.setDrawColor(15, 118, 110);
    doc.setLineWidth(1.5);
    doc.line(M, y, W - M, y);
    y += 16;
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9);
    doc.setTextColor(15, 118, 110);
    const cols = [M, M + 70, M + 130, W - M - 180, W - M - 90, W - M];
    doc.text('Date', cols[0], y);
    doc.text('Ref', cols[1], y);
    doc.text('Description', cols[2], y);
    doc.text('Debit', cols[3], y, { align: 'right' });
    doc.text('Credit', cols[4], y, { align: 'right' });
    doc.text('Balance', cols[5], y, { align: 'right' });
    y += 8;
    doc.setDrawColor(226, 232, 240);
    doc.setLineWidth(0.6);
    doc.line(M, y, W - M, y);
    y += 12;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(30, 41, 59);
    const fmt = function (n) {
      return (typeof formatNairaPlain === 'function') ? formatNairaPlain(n) : ('N' + Number(n || 0).toLocaleString());
    };
    if (!lines.length) {
      doc.text('No movements in this period.', M, y);
    } else {
      lines.forEach(function (ln) {
        if (y > 760) {
          doc.addPage();
          y = 48;
        }
        doc.text(String(ln.date || ''), cols[0], y);
        doc.text(String(ln.ref || '').slice(0, 14), cols[1], y);
        const desc = doc.splitTextToSize(String(ln.description || ''), cols[3] - cols[2] - 8);
        doc.text(desc[0] || '', cols[2], y);
        if (ln.debit) doc.text(fmt(ln.debit), cols[3], y, { align: 'right' });
        if (ln.credit) doc.text(fmt(ln.credit), cols[4], y, { align: 'right' });
        doc.setFont('helvetica', 'bold');
        doc.text(fmt(ln.balance), cols[5], y, { align: 'right' });
        doc.setFont('helvetica', 'normal');
        y += 14;
      });
      y += 8;
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(11);
      doc.text('Closing balance: ' + fmt(lines[lines.length - 1].balance), W - M, y, { align: 'right' });
    }
    const safe = (c.name || 'Client').replace(/[\\/:*?"<>|]/g, ' ').slice(0, 40);
    doc.save(safe + ' - Statement.pdf');
  }).catch(function (e) {
    alert(e.message || 'Could not generate statement PDF.');
  });
}



function drawPdfSignatureBlock(doc, M, W, yStart) {
  try {
    const sig = (typeof COMPANY_SIGNATURE_DATAURL !== 'undefined') ? COMPANY_SIGNATURE_DATAURL : null;
    const stamp = (typeof COMPANY_STAMP_DATAURL !== 'undefined') ? COMPANY_STAMP_DATAURL : null;
    // jsPDF origin is TOP-LEFT (y increases downward) — place stamp at bottom-right
    const H = doc.internal.pageSize.getHeight();
    const stampSize = 140;
    const marginBottom = 36;
    const stampX = W - M - stampSize;
    const stampY = H - marginBottom - stampSize;

    if (stamp) {
      try {
        const fmt = stamp.indexOf('image/png') >= 0 ? 'PNG' : 'JPEG';
        doc.addImage(stamp, fmt, stampX, stampY, stampSize, stampSize);
      } catch (e2) { console.warn('stamp image', e2); }
    }
    // Signature inside stamp over Date / Sign lines
    if (sig) {
      try {
        const fmt = sig.indexOf('image/png') >= 0 ? 'PNG' : 'JPEG';
        const sigW = 95;
        const sigH = 55;
        const sigX = stampX + (stampSize - sigW) / 2;
        const sigY = stampY + stampSize * 0.50 - sigH / 2;
        doc.addImage(sig, fmt, sigX, sigY, sigW, sigH);
      } catch (e1) { console.warn('sig image', e1); }
    }

    return yStart;
  } catch (e) {
    console.warn('signature block', e);
    return yStart;
  }
}

function generateInvoicePdf(inv) {
  const co = data.company || {};
  const client = getClient(inv.clientId);
  const logo = (typeof COMPANY_LOGO_DATAURL !== 'undefined') ? COMPANY_LOGO_DATAURL : null;
  const items = inv.items || [];
  const subtotal = inv.subtotalNgn != null
    ? inv.subtotalNgn
    : items.reduce((s, it) => s + (it.lineNgn != null ? it.lineNgn : (it.qty || 0) * (it.unitNgn || 0)), 0);
  let discountAmt = (inv.discountAmount != null && inv.discountAmount !== '')
    ? Number(inv.discountAmount)
    : NaN;
  let discount = Number(inv.discount) || 0;
  if (isNaN(discountAmt) || discountAmt < 0) {
    discountAmt = subtotal * (discount / 100);
  } else if (subtotal > 0 && !discount) {
    discount = (discountAmt / subtotal) * 100;
  }
  discountAmt = Math.max(0, Math.min(discountAmt, subtotal));
  const total = inv.totalNgn != null ? inv.totalNgn : Math.max(0, subtotal - discountAmt);
  const invNum = inv.invoiceNumber || 'DRAFT';
  const status = (inv.status || 'draft').toUpperCase();
  const dateStr = inv.date ? new Date(inv.date).toLocaleDateString() : new Date().toLocaleDateString();
  const dueStr = inv.dueDate ? new Date(inv.dueDate).toLocaleDateString() : '';

  // Bank: invoice fields first, then company settings
  const bankName = String(inv.bankName || co.bankName || '').trim();
  const accountName = String(inv.accountName || co.accountName || '').trim();
  const accountNumber = String(inv.accountNumber || co.accountNumber || '').trim();
  const bankCode = String(inv.bankCode || co.bankCode || '').trim();
  const hasBank = !!(bankName || accountName || accountNumber || bankCode);

  loadJsPdf().then(JsPDF => {
    const doc = new JsPDF({ unit: 'pt', format: 'a4' });
    const W = doc.internal.pageSize.getWidth();
    const H = doc.internal.pageSize.getHeight();
    const M = 42;
    const TEAL = [15, 118, 110];
    const GRAY = [100, 116, 139];
    const INK = [30, 41, 59];
    const TEAL_BG = [240, 253, 250];
    const LINE = [226, 232, 240];
    const LIGHT = [248, 250, 252];

    doc.setFillColor(255, 255, 255);
    doc.rect(0, 0, W, H, 'F');

    // --- Header only: larger logo left, INVOICE / date / status right (unchanged meta) ---
    const logoW = 240;
    const logoH = logoW * (258 / 1080);
    const headerTop = 36;
    try {
      if (logo) {
        const fmt = logo.indexOf('image/jpeg') >= 0 || logo.indexOf('/9j/') >= 0 ? 'JPEG' : 'PNG';
        doc.addImage(logo, fmt, M, headerTop, logoW, logoH);
      }
    } catch (e) { /* ignore */ }

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(20);
    doc.setTextColor(...TEAL);
    const isPaidDoc = String(inv.status || '').toLowerCase() === 'paid';
    const isProforma = String(inv.docType || '').toLowerCase() === 'proforma';
    // Fully paid → RECEIPT; otherwise invoice / proforma invoice
    const docLabel = isPaidDoc ? 'RECEIPT' : (isProforma ? 'PROFORMA INVOICE' : 'INVOICE');
    doc.text(docLabel, W - M, headerTop + 14, { align: 'right' });
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(12);
    doc.setTextColor(...INK);
    doc.text(String(invNum), W - M, headerTop + 30, { align: 'right' });
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
    doc.setTextColor(...GRAY);
    doc.text('Date: ' + dateStr, W - M, headerTop + 44, { align: 'right' });
    if (dueStr) doc.text('Due date: ' + dueStr, W - M, headerTop + 56, { align: 'right' });
    doc.setTextColor(...INK);
    doc.text('Status: ' + status, W - M, headerTop + 68, { align: 'right' });

    // Divider under header
    const headerBottom = Math.max(headerTop + logoH, headerTop + 72) + 16;
    doc.setDrawColor(...TEAL);
    doc.setLineWidth(2.5);
    doc.line(M, headerBottom, W - M, headerBottom);

    // Estimate body height so the text group sits balanced in the middle of the page
    const addrLines = co.address ? doc.splitTextToSize(co.address, W * 0.7).length : 0;
    const clientAddrLines = (client && client.address) ? doc.splitTextToSize(client.address, W - 2 * M).length : 0;
    const noteLines = inv.notes ? doc.splitTextToSize(String(inv.notes), W - 2 * M - 24).length : 0;
    let bankLines = 0;
    if (hasBank) {
      bankLines = [bankName, accountName, accountNumber, bankCode].filter(Boolean).length;
    }
    const itemCount = Math.max(items.length, 1);
    let estBody = 0;
    estBody += 14 + addrLines * 12 + 24; // company block
    estBody += 14 + 14 + (client && client.contact ? 12 : 0) + clientAddrLines * 12 + 40; // bill to
    estBody += 20 + (inv.quoteRef ? 14 : 0); // title
    estBody += 22 + itemCount * 28 + 20; // table
    estBody += 50 + (discount > 0 ? 16 : 0); // totals
    estBody += hasBank ? (32 + bankLines * 14 + 16) : 20;
    estBody += inv.notes ? (28 + noteLines * 13 + 16) : 0;
    estBody += 50; // footer

    const usableTop = headerBottom + 14;
    const usableBottom = H - 40;
    const usableH = usableBottom - usableTop;
    // Sit content higher on the page (light offset only if lots of spare space)
    let y = usableTop + Math.max(0, Math.min(18, (usableH - estBody) * 0.12));

    // Company block (part of centered group)
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(14);
    doc.setTextColor(...TEAL);
    doc.text(co.name || 'Medicano Resources Limited', M, y);
    y += 14;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9.5);
    doc.setTextColor(...GRAY);
    if (co.address) {
      doc.splitTextToSize(co.address, W * 0.7).forEach(ln => { doc.text(ln, M, y); y += 12; });
    }
    const tel = [co.phone1, co.phone2].filter(Boolean).join(' | ');
    if (tel) { doc.text('Tel: ' + tel, M, y); y += 12; }
    if (co.email) { doc.text(co.email, M, y); y += 12; }
    y += 16;

    // Bill To
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(...GRAY);
    doc.text('BILL TO', M, y);
    y += 14;
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(13);
    doc.setTextColor(...INK);
    doc.text(client ? client.name : '—', M, y);
    y += 14;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
    if (client && client.contact) { doc.text('Attn: ' + client.contact, M, y); y += 12; }
    doc.setTextColor(...GRAY);
    if (client && client.address) {
      doc.splitTextToSize(client.address, W - 2 * M).forEach(ln => { doc.text(ln, M, y); y += 12; });
    }
    if (client && client.phone) { doc.text(client.phone, M, y); y += 12; }
    if (client && client.email) { doc.text(client.email, M, y); y += 12; }
    y += 10;

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(11);
    doc.setTextColor(...INK);
    doc.text('Title: ' + (inv.title || (typeof invoiceDocLabel === 'function' ? invoiceDocLabel(inv) : 'Invoice')), M, y);
    y += 12;
    if (inv.quoteRef) {
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(10);
      doc.setTextColor(...GRAY);
      doc.text('Related quote: ' + inv.quoteRef, M, y);
      y += 14;
    }
    y += 6;

    // Table — Description left; Unit Price / Qty / Amount right-aligned (invoice-style)
    const colDesc = M;
    const colAmount = W - M;
    const amountW = 105;
    const qtyW = 34;
    const unitW = 100;
    const colGap = 10;
    const colQty = colAmount - amountW - colGap;
    const colUnit = colQty - qtyW - colGap;
    const descMaxW = Math.max(100, colUnit - unitW - colGap - colDesc);

    // Header row — text sits between horizontal rules with clear padding
    doc.setDrawColor(...LINE);
    doc.setLineWidth(0.8);
    doc.line(M, y, W - M, y);
    y += 16; // space above header text
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9);
    doc.setTextColor(...TEAL);
    doc.text('Description', colDesc, y);
    doc.text('Unit Price', colUnit, y, { align: 'right' });
    doc.text('Qty', colQty, y, { align: 'right' });
    doc.text('Amount', colAmount, y, { align: 'right' });
    y += 10; // space below header text before rule
    doc.setDrawColor(...LINE);
    doc.setLineWidth(0.8);
    doc.line(M, y, W - M, y);
    y += 4; // small gap after header rule before first row

    items.forEach((it) => {
      if (y > H - 160) { doc.addPage(); y = 48; }
      const prod = it.productId ? getProduct(it.productId) : null;
      const name = it.name || (prod ? prod.name : 'Item');
      const desc = (it.description || (prod && prod.description) || '').trim();
      const qty = Number(it.qty) || 0;
      const unit = Number(it.unitNgn) || 0;
      const line = it.lineNgn != null ? it.lineNgn : qty * unit;

      // Content starts with padding under the previous rule
      y += 14;
      const textY = y;

      doc.setFont('helvetica', 'bold');
      doc.setFontSize(10.5);
      doc.setTextColor(...INK);
      const nameLines = doc.splitTextToSize(String(name), descMaxW);
      doc.text(nameLines[0] || '', colDesc, textY);

      doc.setFont('helvetica', 'normal');
      doc.setFontSize(10);
      doc.setTextColor(...INK);
      doc.text(formatNairaPlain(unit), colUnit, textY, { align: 'right' });
      doc.text(String(qty), colQty, textY, { align: 'right' });
      doc.setFont('helvetica', 'bold');
      doc.text(formatNairaPlain(line), colAmount, textY, { align: 'right' });

      let extra = 0;
      if (desc) {
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(8.5);
        doc.setTextColor(...GRAY);
        const dLines = doc.splitTextToSize(desc, descMaxW).slice(0, 2);
        dLines.forEach((ln, i) => {
          doc.text(ln, colDesc, textY + 13 + i * 11);
        });
        extra = dLines.length * 11 + 2;
      } else if (nameLines.length > 1) {
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(10.5);
        doc.setTextColor(...INK);
        doc.text(nameLines[1], colDesc, textY + 13);
        extra = 13;
      }

      // Keep text clearly above the rule (not sitting on it)
      y = textY + extra + 16;
      doc.setDrawColor(...LINE);
      doc.setLineWidth(0.5);
      doc.line(M, y, W - M, y);
    });

    y += 14;
    // Totals: values right-aligned with Amount column; labels right-aligned so trailing "L" sits on the same edge as amount digits above
    const totalsRight = colAmount;
    const drawTotalLine = (label, value, yPos, bold) => {
      const amountStr = formatNairaPlain(value);
      doc.setFont('helvetica', bold ? 'bold' : 'normal');
      doc.setFontSize(bold ? 13 : 11);
      doc.setTextColor(...(bold ? TEAL : INK));
      doc.text(amountStr, totalsRight, yPos, { align: 'right' });
      const amountW = doc.getTextWidth(amountStr);
      const gap = 14;
      doc.text(label, totalsRight - amountW - gap, yPos, { align: 'right' });
      return totalsRight - amountW - gap - doc.getTextWidth(label);
    };
    const leftEdge = drawTotalLine('Subtotal', subtotal, y, false);
    if (discountAmt > 0.009) {
      y += 16;
      // Label shows approximate %; amount is the exact Naira subtracted
      const pctLabel = (Math.round(discount * 100) / 100).toFixed(discount >= 10 || discount === Math.floor(discount) ? 0 : 2);
      drawTotalLine('Discount (' + pctLabel + '%)', -discountAmt, y, false);
    }
    y += 10;
    doc.setDrawColor(...TEAL);
    doc.setLineWidth(1.5);
    doc.line(Math.min(leftEdge, totalsRight - 120), y, totalsRight, y);
    y += 16;
    drawTotalLine('TOTAL', total, y, true);
    y += 28;

    // Bank / payment details — skip when invoice is already paid
    const isPaid = isPaidDoc;
    if (y > H - 140) { doc.addPage(); y = 50; }
    if (hasBank && !isPaid) {
      const lines = [];
      if (bankName) lines.push('Bank: ' + bankName);
      if (accountName) lines.push('Account name: ' + accountName);
      if (accountNumber) lines.push('Account number: ' + accountNumber);
      if (bankCode) lines.push('Sort / Bank code: ' + bankCode);
      const boxH = 22 + lines.length * 14 + 10;
      doc.setFillColor(...TEAL_BG);
      doc.setDrawColor(153, 246, 228);
      doc.setLineWidth(1);
      doc.roundedRect(M, y - 4, W - 2 * M, boxH, 6, 6, 'FD');
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(9);
      doc.setTextColor(...TEAL);
      doc.text('PAYMENT / BANK DETAILS', M + 12, y + 12);
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(10);
      doc.setTextColor(...INK);
      let by = y + 28;
      lines.forEach(ln => { doc.text(ln, M + 12, by); by += 14; });
      y += boxH + 16;
    }

    // Notes
    if (inv.notes) {
      if (y > H - 100) { doc.addPage(); y = 50; }
      const nlines = doc.splitTextToSize(String(inv.notes), W - 2 * M - 24);
      const nh = 28 + nlines.length * 13;
      doc.setFillColor(...LIGHT);
      doc.roundedRect(M, y - 4, W - 2 * M, nh, 6, 6, 'F');
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(10);
      doc.setTextColor(...INK);
      doc.text('Notes / Payment instructions', M + 12, y + 12);
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(10);
      let ny = y + 28;
      nlines.forEach(ln => { doc.text(ln, M + 12, ny); ny += 13; });
      y += nh + 16;
    }

    if (y > H - 70) { doc.addPage(); y = 50; }
    doc.setDrawColor(...LINE);
    doc.setLineWidth(0.8);
    doc.line(M, y, W - M, y);
    y += 14;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(...GRAY);
    const statusLowerF = String(inv.status || '').toLowerCase();
    const isReceiptDoc = statusLowerF === 'paid';
    if (!isReceiptDoc) {
      doc.text('This invoice is issued by ' + (co.name || 'Medicano Resources Limited') + '. Please make payment by the due date unless otherwise agreed.', M, y);
      y += 12;
    }
    // Exchange rates are no longer printed on invoices / receipts / proformas
    doc.text('Thank you for your business.', M, y);

    // Download file (same as presentation)
    const sanitize = (s, max) => String(s || '')
      .replace(/[\\/:*?"<>|]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, max || 50);
    // Signature + company stamp
    y += 18;
    if (typeof drawPdfSignatureBlock === 'function') {
      y = drawPdfSignatureBlock(doc, M, W, y);
    }
    const clientName = sanitize(client ? client.name : 'Client', 50) || 'Client';
    const kindName = sanitize(typeof invoiceDocLabel === 'function' ? invoiceDocLabel(inv) : (inv.title || 'Invoice'), 40) || 'Invoice';
    const docTitle = sanitize(invNum, 30) || 'Invoice';
    doc.save(clientName + ' - ' + kindName + ' - ' + docTitle + '.pdf');
  }).catch(err => {
    console.error(err);
    alert(err.message || 'Could not generate invoice PDF. Check your connection and try again.');
  });
}


// -------------------- Print / PDF --------------------
function printQuote() {
  if (!currentQuoteId && !document.getElementById('quote-title').value) {
    alert('Save the quote first or fill in the details.');
    return;
  }
  // Use current form state
  const clientId = document.getElementById('quote-client').value;
  const client = getClient(clientId);
  const title = document.getElementById('quote-title').value || 'Untitled';
  const valid = document.getElementById('quote-valid').value;
  const notes = document.getElementById('quote-notes').value;
  const discount = parseFloat(document.getElementById('quote-discount').value) || 0;
  const status = document.getElementById('quote-status').value;

  let itemsHtml = '';
  let subtotal = 0;
  document.querySelectorAll('#quote-items-list .line-card').forEach(row => {
    const productId = row.querySelector('.qi-product')?.value || '';
    const p = productId ? getProduct(productId) : null;
    const name = (row.querySelector('.qi-name')?.value || '').trim() || (p ? p.name : '');
    if (!name && !productId) return;
    const sku = p ? p.sku : (row.dataset.sku || '');
    const qty = parseFloat(row.querySelector('.qi-qty')?.value) || 1;
    const unit = parseFloat(row.dataset.unitNgn) || 0;
    const line = qty * unit;
    subtotal += line;
    // Final unit only — no base/markup shown on quotation
    itemsHtml += `<tr>
      <td style="padding:8px;border-bottom:1px solid #e2e8f0;">${sku ? escHtml(sku) + '<br>' : ''}<small>${escHtml(name)}</small></td>
      <td style="padding:8px;border-bottom:1px solid #e2e8f0;text-align:center;">${qty}</td>
      <td style="padding:8px;border-bottom:1px solid #e2e8f0;text-align:right;">${formatNGN(unit)}</td>
      <td style="padding:8px;border-bottom:1px solid #e2e8f0;text-align:right;">${formatNGN(line)}</td>
    </tr>`;
  });

  const total = subtotal * (1 - discount / 100);
  const quoteNum = currentQuoteId
    ? (data.quotes.find(q => q.id === currentQuoteId) || {}).quoteNumber || 'DRAFT'
    : 'DRAFT';

  const co = data.company;
  const html = `
    <div style="font-family: system-ui, sans-serif; color: #1e293b;">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #0f766e;padding-bottom:16px;margin-bottom:24px;">
        <div>
          <h1 style="margin:0;font-size:22px;color:#0f766e;">${co.name}</h1>
          <p style="margin:4px 0 0;font-size:12px;color:#64748b;">${co.address}</p>
          <p style="margin:2px 0;font-size:12px;color:#64748b;">Tel: ${co.phone1} | ${co.phone2}</p>
          <p style="margin:2px 0;font-size:12px;color:#64748b;">${co.email}</p>
        </div>
        <div style="text-align:right;">
          <h2 style="margin:0;font-size:20px;color:#0f766e;">QUOTATION</h2>
          <p style="margin:8px 0 0;font-size:13px;"><strong>${quoteNum}</strong></p>
          <p style="margin:2px 0;font-size:12px;color:#64748b;">Date: ${new Date().toLocaleDateString()}</p>
          ${valid ? `<p style="margin:2px 0;font-size:12px;color:#64748b;">Valid until: ${valid}</p>` : ''}
          <p style="margin:2px 0;font-size:12px;">Status: ${status.toUpperCase()}</p>
        </div>
      </div>

      <div style="margin-bottom:24px;">
        <p style="margin:0;font-size:11px;color:#64748b;text-transform:uppercase;">Bill To</p>
        <p style="margin:4px 0 0;font-weight:600;font-size:15px;">${client ? client.name : '—'}</p>
        ${client && client.contact ? `<p style="margin:2px 0;font-size:13px;">Attn: ${client.contact}</p>` : ''}
        ${client && client.address ? `<p style="margin:2px 0;font-size:12px;color:#64748b;">${client.address}</p>` : ''}
        ${client && client.phone ? `<p style="margin:2px 0;font-size:12px;color:#64748b;">${client.phone}</p>` : ''}
      </div>

      <p style="font-weight:600;margin-bottom:8px;">Project / Title: ${title}</p>

      <table style="width:100%;border-collapse:collapse;font-size:13px;margin-bottom:24px;">
        <thead>
          <tr style="background:#f0fdfa;text-align:left;">
            <th style="padding:10px 8px;border-bottom:2px solid #0f766e;">Item</th>
            <th style="padding:10px 8px;border-bottom:2px solid #0f766e;text-align:center;">Qty</th>
            <th style="padding:10px 8px;border-bottom:2px solid #0f766e;text-align:right;">Unit Price</th>
            <th style="padding:10px 8px;border-bottom:2px solid #0f766e;text-align:right;">Unit (NGN)</th>
            <th style="padding:10px 8px;border-bottom:2px solid #0f766e;text-align:right;">Line Total (NGN)</th>
          </tr>
        </thead>
        <tbody>${itemsHtml}</tbody>
      </table>

      <div style="display:flex;justify-content:flex-end;">
        <div style="width:260px;font-size:13px;">
          <div style="display:flex;justify-content:space-between;padding:4px 0;">
            <span>Subtotal</span><span>${formatNGN(subtotal)}</span>
          </div>
          ${discount > 0 ? `<div style="display:flex;justify-content:space-between;padding:4px 0;"><span>Discount (${discount}%)</span><span>-${formatNGN(subtotal * discount / 100)}</span></div>` : ''}
          <div style="display:flex;justify-content:space-between;padding:8px 0;border-top:2px solid #0f766e;font-weight:700;font-size:16px;color:#0f766e;">
            <span>TOTAL (NGN)</span><span>${formatNGN(total)}</span>
          </div>
        </div>
      </div>

      ${notes ? `<div style="margin-top:32px;padding:12px;background:#f8fafc;border-radius:6px;font-size:12px;"><strong>Notes / Terms</strong><br>${notes.replace(/\n/g, '<br>')}</div>` : ''}

      <div style="margin-top:48px;font-size:11px;color:#64748b;border-top:1px solid #e2e8f0;padding-top:12px;">
        <p>This quotation is generated by Medicano Resources Limited. Prices are converted to Naira using the prevailing rates at the time of quotation.</p>
        <p style="margin-top:4px;">Current rates: 1 USD = ₦${data.rates.USD.toLocaleString()} | 1 EUR = ₦${data.rates.EUR.toLocaleString()}</p>
        <p style="margin-top:16px;">Thank you for your business.</p>
      </div>
    </div>
  `;

  // Open a clean new window with ONLY the quote (no app UI / screenshot)
  const printWin = window.open('', '_blank', 'width=900,height=700');
  if (!printWin) {
    alert('Please allow pop-ups to print the quotation.');
    return;
  }
  const clientName = client ? client.name : 'Client';
  // Clean name for filename suggestion (remove characters that are bad in filenames)
  const safeClientName = clientName.replace(/[\\/:*?"<>|]/g, ' ').replace(/\s+/g, ' ').trim();
  const docTitle = `Quotation ${quoteNum} - ${safeClientName}`;

  printWin.document.write(`<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>${docTitle}</title>
  <style>
    body { font-family: system-ui, -apple-system, sans-serif; color: #1e293b; margin: 0; padding: 24px; }
    @media print {
      body { padding: 0; }
      @page { margin: 15mm; }
    }
  </style>
</head>
<body>
  ${html}
  <script>
    window.onload = function() {
      window.print();
    };
  <\/script>
</body>
</html>`);
  printWin.document.close();
}

// -------------------- Rates --------------------
function renderRates() {
  document.getElementById('rate-usd').value = data.rates.USD;
  document.getElementById('rate-eur').value = data.rates.EUR;
  const mode = data.rates.mode || 'manual';
  document.querySelectorAll('input[name="rate-mode"]').forEach(r => {
    r.checked = r.value === mode;
  });
  onRateModeChange();
  document.getElementById('rates-updated').textContent = data.rates.updatedAt
    ? 'Last updated: ' + new Date(data.rates.updatedAt).toLocaleString()
    : '';
}

function onRateModeChange() {
  const mode = document.querySelector('input[name="rate-mode"]:checked')?.value || 'manual';
  const fetchBtn = document.getElementById('btn-fetch-rates');
  const usd = document.getElementById('rate-usd');
  const eur = document.getElementById('rate-eur');
  if (fetchBtn) fetchBtn.classList.toggle('hidden', mode !== 'auto');
  if (usd) usd.readOnly = mode === 'auto';
  if (eur) eur.readOnly = mode === 'auto';
  if (mode === 'auto') {
    usd.style.opacity = '0.85';
    eur.style.opacity = '0.85';
  } else {
    usd.style.opacity = '1';
    eur.style.opacity = '1';
  }
}

function saveRates() {
  const mode = document.querySelector('input[name="rate-mode"]:checked')?.value || 'manual';
  data.rates.mode = mode;
  if (mode === 'manual') {
    data.rates.USD = parseFloat(document.getElementById('rate-usd').value) || data.rates.USD;
    data.rates.EUR = parseFloat(document.getElementById('rate-eur').value) || data.rates.EUR;
    data.rates.updatedAt = new Date().toISOString();
  }
  saveData();
  updateRatesDisplay();
  renderRates();
  alert(mode === 'auto' ? 'Auto mode saved. Use “Fetch latest rates” to update.' : 'Exchange rates saved.');
}

async function fetchAutoRates() {
  const status = document.getElementById('rates-status');
  if (status) status.textContent = 'Fetching rates…';
  try {
    // Free API — no key required (open.er-api.com)
    const res = await fetch('https://open.er-api.com/v6/latest/USD');
    if (!res.ok) throw new Error('Network error');
    const json = await res.json();
    if (json.result !== 'success' || !json.rates || !json.rates.NGN) {
      throw new Error('Unexpected API response');
    }
    const usdNgn = json.rates.NGN;
    // EUR from USD: NGN per EUR ≈ NGN/USD * USD/EUR = NGN/USD / (EUR rate in USD terms)
    // json.rates.EUR is how many EUR per 1 USD, so 1 EUR in NGN = usdNgn / json.rates.EUR
    const eurNgn = json.rates.EUR ? (usdNgn / json.rates.EUR) : data.rates.EUR;

    data.rates.USD = Math.round(usdNgn * 100) / 100;
    data.rates.EUR = Math.round(eurNgn * 100) / 100;
    data.rates.mode = 'auto';
    data.rates.updatedAt = new Date().toISOString();
    saveData();
    updateRatesDisplay();
    renderRates();
    if (status) status.textContent = 'Rates updated from open.er-api.com';
    alert('Latest rates fetched successfully.');
  } catch (err) {
    console.error(err);
    if (status) status.textContent = 'Could not fetch rates. Check internet or use Manual mode.';
    alert('Could not fetch rates. Stay on Manual mode or try again when online.');
  }
}

