function parseCsv(text) {
  const rows = [];
  let row = [], cell = '', i = 0, inQuotes = false;
  const s = text.replace(/^\uFEFF/, '');
  while (i < s.length) {
    const c = s[i];
    if (inQuotes) {
      if (c === '"') {
        if (s[i + 1] === '"') { cell += '"'; i += 2; continue; }
        inQuotes = false; i++; continue;
      }
      cell += c; i++; continue;
    }
    if (c === '"') { inQuotes = true; i++; continue; }
    if (c === ',') { row.push(cell); cell = ''; i++; continue; }
    if (c === '\n' || c === '\r') {
      if (c === '\r' && s[i + 1] === '\n') i++;
      row.push(cell); cell = '';
      if (row.some(x => String(x).trim() !== '')) rows.push(row);
      row = []; i++; continue;
    }
    cell += c; i++;
  }
  row.push(cell);
  if (row.some(x => String(x).trim() !== '')) rows.push(row);
  return rows;
}

function normalizeHeader(h) {
  return String(h || '').trim().toLowerCase().replace(/[_\s]+/g, ' ');
}

function importProductsFromCsv(file) {
  const reader = new FileReader();
  reader.onload = (ev) => {
    try {
      const rows = parseCsv(ev.target.result);
      if (rows.length < 2) {
        alert('Spreadsheet is empty or has no data rows.');
        return;
      }
      const headers = rows[0].map(normalizeHeader);
      const col = (...names) => {
        for (const n of names) {
          const idx = headers.indexOf(n);
          if (idx >= 0) return idx;
        }
        return -1;
      };
      const iSku = col('sku', 'code', 'product code', 'item code', 'variant sku', 'parent sku');
      const iName = col('name', 'equipment', 'product', 'item', 'parent name', 'full description', 'description of products', 'variant label');
      const iCat = col('category');
      const iBrand = col('brand');
      const iDesc = col('description', 'description / specs', 'specs', 'full description');
      const iFeat = col('features', 'key features', 'variant label');
      const iPrice = col('price', 'price eur', 'price euro', 'price display', 'unit price');
      const iCur = col('currency');
      const priceEurHint = headers.some(h => h.includes('eur') || h.includes('euro'));
      const iStock = col('stock', 'stock qty', 'qty');
      const iLow = col('low stock', 'low stock alert');
      const iActive = col('active');

      if (iSku < 0 || iName < 0 || iPrice < 0) {
        alert('Spreadsheet must have at least: SKU, Name, Price\n\nDownload the template for the correct format.');
        return;
      }

      let added = 0, updated = 0, skipped = 0;
      if (!data.categories) data.categories = [];

      for (let r = 1; r < rows.length; r++) {
        const row = rows[r];
        const sku = String(row[iSku] || '').trim();
        const name = String(row[iName] || '').trim();
        if (!sku || !name) { skipped++; continue; }

        const price = parseFloat(String(row[iPrice] || '0').replace(/,/g, '')) || 0;
        let currency = iCur >= 0 ? String(row[iCur] || 'USD').trim().toUpperCase() : 'USD';
        if (!['USD', 'EUR', 'NGN'].includes(currency)) currency = 'USD';
        const category = iCat >= 0 ? String(row[iCat] || 'General').trim() : 'General';
        const brand = iBrand >= 0 ? String(row[iBrand] || '').trim() : '';
        const description = iDesc >= 0 ? String(row[iDesc] || '').trim() : '';
        const features = iFeat >= 0 ? String(row[iFeat] || '').trim() : '';
        const stock = iStock >= 0 ? parseInt(row[iStock], 10) || 0 : 0;
        const lowStock = iLow >= 0 ? parseInt(row[iLow], 10) || 0 : 2;
        let active = true;
        if (iActive >= 0) {
          const a = String(row[iActive] || 'yes').trim().toLowerCase();
          active = !(a === 'no' || a === 'false' || a === '0' || a === 'inactive');
        }

        if (category && !data.categories.some(c => c.toLowerCase() === category.toLowerCase())) {
          data.categories.push(category);
        }

        const existing = data.products.find(p => p.sku.toLowerCase() === sku.toLowerCase());
        if (existing) {
          existing.name = name;
          existing.category = category;
          existing.brand = brand;
          existing.description = description;
          existing.features = features;
          existing.price = price;
          existing.currency = currency;
          existing.stock = stock;
          existing.lowStock = lowStock;
          existing.active = active;
          updated++;
        } else {
          data.products.push({
            id: uid(),
            sku, name, category, brand, description, features,
            price, currency, stock, lowStock, active, image: ''
          });
          added++;
        }
      }

      data.categories.sort();
      window._productTimestampsReady = false;
      if (typeof saveDataNow === 'function') saveDataNow();
      else saveData();
      renderProducts();
      renderDashboard();
      if (typeof populateCategorySelect === 'function') populateCategorySelect();
      var syncNote = '';
      var cloud = window.MedicanoCloud;
      if (cloud && cloud.pushNow) {
        cloud.pushNow().then(function (res) {
          if (res && res.ok) {
            syncNote = '\n\nCloud sync: published ' + ((res.products != null) ? res.products : (data.products || []).length) + ' items to the team.';
          } else {
            syncNote = '\n\nCloud sync did not finish (' + ((res && (res.reason || res.error && res.error.message)) || 'check sign-in / Firestore rules for productChunks') + '). Data is saved on this device only until sync succeeds.';
          }
          alert('Import complete.\n\nAdded: ' + added + '\nUpdated: ' + updated + '\nSkipped: ' + skipped + syncNote);
        }).catch(function (e) {
          alert('Import complete.\n\nAdded: ' + added + '\nUpdated: ' + updated + '\nSkipped: ' + skipped + '\n\nCloud sync error: ' + (e && e.message ? e.message : e) + '\n\nUpdate Firestore rules for productChunks, stay signed in as admin, then use Force sync.');
        });
      } else {
        alert('Import complete.\n\nAdded: ' + added + '\nUpdated: ' + updated + '\nSkipped: ' + skipped + '\n\nNot signed in to cloud — items are only on this device.');
      }
    } catch (err) {
      console.error(err);
      alert('Could not read the spreadsheet. Save as CSV (UTF-8) from Excel and try again.');
    }
  };
  reader.readAsText(file);
}

function onImportProductsFile(e) {
  const file = e.target.files && e.target.files[0];
  if (!file) return;
  const name = file.name.toLowerCase();
  if (name.endsWith('.xlsx') || name.endsWith('.xls')) {
    alert('Please save your Excel file as CSV first:\n\nFile → Save As → CSV (Comma delimited)\n\nThen import the .csv file.');
    e.target.value = '';
    return;
  }
  importProductsFromCsv(file);
  e.target.value = '';
}

