function applyQuoteToPresentation() {
  const id = document.getElementById('pres-from-quote')?.value;
  if (!id) { alert('Select a quotation first.'); return; }
  const q = (data.quotes || []).find(x => x.id === id);
  if (!q) { alert('Quote not found.'); return; }
  const client = getClient(q.clientId);
  if (client && document.getElementById('pres-client')) {
    document.getElementById('pres-client').value = client.name || '';
  }
  if (q.title && document.getElementById('pres-title')) {
    document.getElementById('pres-title').value = q.title;
  }
  // Store quote items for generatePresentation
  window._presQuoteItems = (q.items || []).map(it => {
    const p = it.productId ? getProduct(it.productId) : null;
    const unit = it.unitNGN != null ? it.unitNGN : (it.unitNgn != null ? it.unitNgn : (p ? toNGN(p.price, p.currency) : 0));
    const qty = it.qty || 1;
    return {
      id: it.productId || ('custom-' + (it.name || 'item') + '-' + Math.random().toString(36).slice(2, 6)),
      productId: it.productId || '',
      name: it.name || (p ? p.name : 'Item'),
      sku: it.sku || (p ? p.sku : ''),
      category: (p && p.category) || 'General',
      description: (p && p.description) || '',
      features: (p && p.features) || '',
      image: (p && p.image) || '',
      price: unit,
      currency: 'NGN',
      qty: qty,
      fromQuote: true
    };
  });
  // Also check catalog products that match
  const picker = document.getElementById('pres-picker');
  if (picker) {
    picker.querySelectorAll('.pres-check').forEach(cb => { cb.checked = false; });
    (q.items || []).forEach(it => {
      if (!it.productId) return;
      const cb = picker.querySelector('.pres-check[value="' + it.productId + '"]');
      if (cb) cb.checked = true;
    });
  }
  alert('Loaded ' + (window._presQuoteItems || []).length + ' item(s) from ' + (q.quoteNumber || 'quote') + '. Generate PDF when ready.');
}

function renderPresPicker() {
  populatePresQuoteSelect();
  const search = (document.getElementById('pres-search')?.value || '').toLowerCase();
  const container = document.getElementById('pres-picker');
  if (!container) return;

  const list = data.products.filter(p => p.active).filter(p =>
    !search ||
    (p.name || '').toLowerCase().includes(search) ||
    (p.sku || '').toLowerCase().includes(search) ||
    (p.category || '').toLowerCase().includes(search) ||
    (p.brand || '').toLowerCase().includes(search) ||
    (p.description || '').toLowerCase().includes(search)
  );

  if (list.length === 0) {
    container.innerHTML = '<p class="p-4 text-slate-400 text-center">No items found</p>';
    return;
  }

  // Payment-style select rows: all inventory details, no images / no icons
  // Price: Naira only, bold, same size as name, bottom-right of card
  container.innerHTML = list.map(p => {
    const ngnStr = formatNGN(toNGN(p.price, p.currency));
    const stock = Number(p.stock) || 0;
    const low = stock <= (Number(p.lowStock) || 1);
    const meta = [
      p.sku ? `SKU ${p.sku}` : null,
      p.category || null,
      p.brand || null,
      `Stock ${stock}${low ? ' · low' : ''}`
    ].filter(Boolean).join(' · ');
    const desc = (p.description || '').trim();
    const features = (p.features || '').trim();
    const subParts = [meta];
    if (desc) subParts.push(desc.length > 160 ? desc.slice(0, 157) + '…' : desc);
    if (features) subParts.push(features.length > 120 ? features.slice(0, 117) + '…' : features);
    const sub = subParts.map(s => escHtml(s)).join('<br>');
    return `<label class="select-row pres-pick-row">
      <span class="select-row-text">
        <span class="select-row-title">${escHtml(p.name || 'Untitled')}</span>
        <span class="select-row-sub">${sub}</span>
      </span>
      <span class="pres-pick-aside">
        <input type="checkbox" class="pres-check select-row-check" value="${escHtml(p.id)}" />
        <span class="pres-pick-price">${escHtml(ngnStr)}</span>
      </span>
    </label>`;
  }).join('');
}

function selectAllPres(checked) {
  document.querySelectorAll('#pres-picker .pres-check').forEach(cb => { cb.checked = checked; });
}

function formatNairaPlain(n) {
  const v = Number(n) || 0;
  return 'N' + v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function loadJsPdf() {
  return new Promise((resolve, reject) => {
    if (window.jspdf && window.jspdf.jsPDF) return resolve(window.jspdf.jsPDF);
    if (window.jsPDF) return resolve(window.jsPDF);
    // Prefer local copy (offline / APK), then CDN
    function trySrc(src, next) {
      const s = document.createElement('script');
      s.src = src;
      s.onload = function () {
        const C = (window.jspdf && window.jspdf.jsPDF) || window.jsPDF;
        if (C) resolve(C);
        else if (next) next();
        else reject(new Error('PDF engine loaded but jsPDF was not found.'));
      };
      s.onerror = function () {
        if (next) next();
        else reject(new Error('Could not load PDF engine. Check that jspdf.umd.min.js is in the app folder.'));
      };
      document.head.appendChild(s);
    }
    trySrc('jspdf.umd.min.js', function () {
      trySrc('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js');
    });
  });
}

function generatePresentation() {
  const checked = [...document.querySelectorAll('#pres-picker .pres-check:checked')];
  const quoteItems = window._presQuoteItems || [];
  let products = [];
  if (quoteItems.length) {
    // Prefer quote-loaded items (includes qty + unit price); merge any extra checked products not already included
    const ids = new Set(quoteItems.map(x => x.productId).filter(Boolean));
    products = quoteItems.slice();
    checked.forEach(cb => {
      if (ids.has(cb.value)) return;
      const p = getProduct(cb.value);
      if (p) products.push({ ...p, qty: 1, price: toNGN(p.price, p.currency), currency: 'NGN' });
    });
  } else {
    products = checked.map(cb => {
      const p = getProduct(cb.value);
      if (!p) return null;
      return { ...p, qty: 1, price: toNGN(p.price, p.currency), currency: 'NGN' };
    }).filter(Boolean);
  }
  if (products.length === 0) {
    alert('Select equipment or load a quotation first.');
    return;
  }
  const forClient = document.getElementById('pres-client')?.value.trim() || 'Our Valued Hospital Partner';
  const co = data.company;
  const dateStr = new Date().toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
  const title = document.getElementById('pres-title')?.value.trim() || 'Medical Equipment Proposal';
  const layout = (document.querySelector('input[name="pres-layout"]:checked')?.value) || 'picture';
  const summaryMode = (document.querySelector('input[name="pres-summary"]:checked')?.value) || 'complex';
  const globalMarkup = parseFloat(document.getElementById('pres-global-markup')?.value) || 0;

  const btn = document.querySelector('#page-presentation button[onclick="generatePresentation()"]');
  if (btn) { btn.disabled = true; btn.textContent = 'Generating PDF…'; }

  loadJsPdf().then(JsPDF => {
    buildPresentationPdf(JsPDF, products, co, forClient, dateStr, title, layout, summaryMode, globalMarkup);
  }).catch(err => {
    alert(err.message || 'PDF generation failed.');
  }).finally(() => {
    if (btn) { btn.disabled = false; btn.textContent = 'Generate High-Quality PDF Presentation'; }
  });
}

function buildPresentationPdf(JsPDF, products, co, forClient, dateStr, title, layout, summaryMode, globalMarkup) {
  const doc = new JsPDF({ unit: 'pt', format: 'a4', orientation: 'portrait' });
  const W = doc.internal.pageSize.getWidth();  // 595.28
  const H = doc.internal.pageSize.getHeight(); // 841.89
  const M = 42;
  const NAVY = [11, 22, 38];
  const NAVY2 = [24, 44, 68];
  const GOLD = [196, 162, 96];
  const GOLDSOFT = [214, 190, 140];
  const CREAM = [247, 244, 237];
  const CREAM2 = [238, 233, 222];
  const INK = [30, 30, 32];
  const GRAY = [110, 112, 118];
  const LINE = [222, 216, 202];
  const WHITE = [255, 255, 255];

  const setCol = (rgb) => doc.setTextColor(rgb[0], rgb[1], rgb[2]);
  const setFill = (rgb) => doc.setFillColor(rgb[0], rgb[1], rgb[2]);
  const setDraw = (rgb) => doc.setDrawColor(rgb[0], rgb[1], rgb[2]);

  // Standard body size matches T&C body (12.5pt)
  const BODY = 12.5;
  const BODY_LEAD = 16;
  const isList = (layout === 'list' || layout === 'brochure');
  const isSimpleSummary = (summaryMode === 'simple');
  const isUltraSummary = (summaryMode === 'ultra');
  const globalMk = parseFloat(globalMarkup) || 0;

  function wrap(text, fontSize, maxW, font='normal') {
    doc.setFont('helvetica', font);
    doc.setFontSize(fontSize);
    return doc.splitTextToSize(String(text || ''), maxW);
  }

  // Top running header — keep clear of page titles below
  function footer(pageNo, total) {
    setCol(GRAY);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.text((co.name || 'MEDICANO RESOURCES LIMITED').toUpperCase(), M, 22);
    setCol([115, 128, 140]);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(14);
    doc.text(String(pageNo).padStart(2, '0') + ' / ' + String(total).padStart(2, '0'), W - M, 24, { align: 'right' });
  }

  function lineUnitBase(p) {
    return (p.currency === 'NGN' || p.fromQuote) ? (parseFloat(p.price) || 0) : toNGN(p.price, p.currency);
  }
  function lineUnit(p) {
    return lineUnitBase(p) * (1 + globalMk / 100);
  }
  function lineQty(p) {
    return Math.max(1, parseFloat(p.qty) || 1);
  }
  function lineTotal(p) {
    return lineUnit(p) * lineQty(p);
  }

  function estimateCardH(p) {
    if (isList) {
      const nameLines = Math.min(2, Math.max(1, wrap(p.name || '', 10.5, W - 2 * M - 160, 'bold').length));
      const desc = String(p.description || '').trim();
      const descLines = desc ? Math.min(2, wrap(desc, 9, W - 2 * M - 160).length) : 0;
      return Math.max(52, 28 + nameLines * 12 + descLines * 11 + 18);
    }
    const feats = (p.features || '').split('\n').map(f => f.trim()).filter(Boolean).length;
    const descLines = Math.max(1, wrap(p.description || '', BODY, W - 2 * M - 140).length);
    let h = 100 + descLines * BODY_LEAD + Math.max(feats, 0) * (BODY_LEAD - 1) + 28;
    return Math.max(150, Math.min(h + 12, 280));
  }

  function packMachines(list) {
    // More cards when content is short; list mode packs denser
    const usable = isList ? 620 : 560;
    const gap = isList ? 6 : 12;
    const maxPerPage = isList ? 14 : 4;
    const heights = list.map(estimateCardH);
    const packs = [];
    let i = 0;
    while (i < list.length) {
      const items = [];
      let used = 0;
      while (i < list.length) {
        const h = heights[i];
        const need = items.length ? h + gap : h;
        if (items.length && used + need > usable) break;
        items.push({ p: list[i], h, idx: i });
        used += need;
        i++;
        if (items.length >= maxPerPage) break;
      }
      packs.push({ items, usedH: used, gap });
    }
    return packs;
  }

  function drawPictureCard(p, x, y, w, h) {
    setFill(WHITE); setDraw(LINE); doc.setLineWidth(0.75);
    doc.roundedRect(x, y, w, h, 8, 8, 'FD');
    const pad = 14;
    const imgSize = Math.min(118, h - 2 * pad);
    const imgY = y + pad + Math.max(0, (h - 2 * pad - imgSize) / 2);
    setFill(NAVY2); setDraw(GOLD); doc.setLineWidth(1);
    doc.roundedRect(x + pad, imgY, imgSize, imgSize, 4, 4, 'FD');
    if (p.image) {
      try {
        doc.addImage(p.image, 'JPEG', x + pad + 1, imgY + 1, imgSize - 2, imgSize - 2);
      } catch (e) {
        setCol(GOLDSOFT); doc.setFont('helvetica', 'normal'); doc.setFontSize(16);
        doc.text('EQ', x + pad + imgSize / 2, imgY + imgSize / 2 + 5, { align: 'center' });
      }
    } else {
      setCol(GOLDSOFT); doc.setFont('helvetica', 'normal'); doc.setFontSize(16);
      doc.text('EQ', x + pad + imgSize / 2, imgY + imgSize / 2 + 5, { align: 'center' });
    }
    const tx = x + pad + imgSize + 16;
    const tw = w - (pad + imgSize + 16) - pad;
    let ty = y + pad + 12;
    setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(7.4);
    doc.text(String(p.category || 'EQUIPMENT').toUpperCase(), tx, ty);
    ty += 16;
    setCol(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(13);
    wrap(p.name, 13, tw, 'bold').slice(0, 2).forEach(ln => { doc.text(ln, tx, ty); ty += 14; });
    setDraw(LINE); doc.setLineWidth(1); doc.line(tx, ty, tx + 28, ty);
    ty += 14;
    setCol([87, 88, 92]); doc.setFont('helvetica', 'normal'); doc.setFontSize(BODY);
    wrap(p.description || '', BODY, tw).slice(0, 4).forEach(ln => { doc.text(ln, tx, ty); ty += BODY_LEAD - 2; });
    ty += 6;
    (p.features || '').split('\n').map(f => f.trim()).filter(Boolean).slice(0, 5).forEach(f => {
      setFill(GOLD); doc.circle(tx + 3, ty - 2, 1.6, 'F');
      setCol([56, 57, 61]); doc.setFont('helvetica', 'normal'); doc.setFontSize(BODY);
      doc.text(f.substring(0, 72), tx + 10, ty);
      ty += BODY_LEAD - 1;
    });
    const unitNgn = lineUnit(p);
    const qty = lineQty(p);
    const lineNgn = unitNgn * qty;
    setCol(GRAY); doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
    doc.text('PRICE', x + w - pad, y + h - pad - 28, { align: 'right' });
    setCol([115, 118, 124]); doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5);
    doc.text(formatNairaPlain(unitNgn) + ' × (' + qty + (qty === 1 ? ' unit' : ' units') + ')', x + w - pad, y + h - pad - 16, { align: 'right' });
    setCol(NAVY); doc.setFontSize(BODY); doc.setFont('helvetica', 'bold');
    doc.text(formatNairaPlain(lineNgn), x + w - pad, y + h - pad - 2, { align: 'right' });
  }

  function drawListCard(p, x, y, w, h) {
    setFill(WHITE); setDraw(LINE); doc.setLineWidth(0.55);
    doc.roundedRect(x, y, w, h, 5, 5, 'FD');
    const padX = 12;
    const padY = 10;
    let ty = y + padY + 8;
    setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(6.5);
    doc.text(String(p.category || 'EQUIPMENT').toUpperCase(), x + padX, ty);
    // price block right
    const unitNgn = lineUnit(p);
    const qty = lineQty(p);
    const lineNgn = unitNgn * qty;
    setCol([115, 118, 124]); doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
    doc.text(formatNairaPlain(unitNgn) + ' × (' + qty + (qty === 1 ? ' unit' : ' units') + ')', x + w - padX, ty, { align: 'right' });
    ty += 12;
    setCol(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(10.5);
    const nameMax = w - padX * 2 - 120;
    wrap(p.name || '', 10.5, nameMax, 'bold').slice(0, 2).forEach(ln => { doc.text(ln, x + padX, ty); ty += 12; });
    setCol(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
    doc.text(formatNairaPlain(lineNgn), x + w - padX, y + padY + 22, { align: 'right' });
    const desc = String(p.description || '').trim();
    if (desc) {
      setCol([90, 92, 98]); doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
      wrap(desc, 9, w - padX * 2 - 100).slice(0, 2).forEach(ln => { doc.text(ln, x + padX, ty); ty += 11; });
    }
  }

  function drawCard(p, x, y, w, h) {
    if (isList) drawListCard(p, x, y, w, h);
    else drawPictureCard(p, x, y, w, h);
  }

  // Multi-page pricing summary — continues before footer when long
  function drawSummaryPages(list, startPageNo, totalPagesGuess) {
    const rowH = 28;
    const topY = 122;
    const bottomSafe = 58;
    const maxRowsFirst = Math.floor((H - topY - bottomSafe - 90) / rowH);
    const maxRowsCont = Math.floor((H - topY - bottomSafe - 40) / rowH);
    const chunks = [];
    let i = 0;
    let first = true;
    while (i < list.length) {
      const n = first ? Math.max(1, maxRowsFirst) : Math.max(1, maxRowsCont);
      chunks.push(list.slice(i, i + n));
      i += n;
      first = false;
    }
    if (!chunks.length) chunks.push([]);

    let pageNo = startPageNo;
    const grandTotal = list.reduce((s, p) => s + lineTotal(p), 0);

    chunks.forEach((chunk, ci) => {
      if (ci > 0) doc.addPage();
      setFill(CREAM); doc.rect(0, 0, W, H, 'F');
      setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
      doc.text('INVESTMENT', M, 58);
      setCol(NAVY); doc.setFontSize(22);
      doc.text(ci === 0 ? 'Pricing Summary' : 'Pricing Summary (continued)', M, 86);
      setDraw(GOLD); doc.setLineWidth(1.5); doc.line(M, 102, M + 54, 102);

      const isLast = ci === chunks.length - 1;
      const panelTop = topY;
      const rowsH = chunk.length * rowH;
      const totalBand = isLast ? 52 : 0;
      const noteH = isLast ? 22 : 0;
      const panelH = 36 + rowsH + 16 + totalBand + noteH + 24;
      const cardW = W - 2 * M;

      setFill(NAVY);
      doc.roundedRect(M, panelTop, cardW, Math.min(panelH, H - panelTop - bottomSafe + 8), 10, 10, 'F');

      setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(12);
      doc.text(ci === 0 ? 'PRICING SUMMARY' : 'CONTINUED', M + 28, panelTop + 28);

      let ry = panelTop + 48;
      chunk.forEach(p => {
        if (ry > H - bottomSafe - (isLast ? 70 : 20)) return;
        setCol(CREAM2); doc.setFont('helvetica', 'normal'); doc.setFontSize(11);
        const qty = lineQty(p);
        const name = String(p.name || '').substring(0, 40) + (qty > 1 ? ' ×' + qty : '');
        doc.text(name, M + 28, ry);
        doc.setFont('helvetica', 'bold');
        doc.text(formatNairaPlain(lineTotal(p)), W - M - 28, ry, { align: 'right' });
        ry += rowH;
      });

      if (isLast) {
        setDraw([80, 100, 120]); doc.setLineWidth(0.9);
        doc.line(M + 28, ry - 6, W - M - 28, ry - 6);
        ry += 18;
        setCol(CREAM); doc.setFont('helvetica', 'bold'); doc.setFontSize(13);
        doc.text('TOTAL PROPOSAL VALUE', M + 28, ry);
        setCol(GOLD); doc.setFontSize(16);
        doc.text(formatNairaPlain(grandTotal), W - M - 28, ry, { align: 'right' });
        ry += 22;
        setCol([160, 170, 185]); doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
        doc.text('Prices are indicative and exclude installation, freight, and applicable duties.', M + 28, ry);
      } else {
        setCol([160, 170, 185]); doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
        doc.text('Continued on next page…', M + 28, ry + 4);
      }

      footer(pageNo, totalPagesGuess);
      pageNo++;
    });
    return pageNo;
  }

  // Ultra-simple table summary (image-style: navy header, zebra rows)
  function drawUltraSummaryPages(list, startPageNo, totalPagesGuess, firstTopY) {
    // Item | Qty | Original Unit Price | Line Total — no title; multi-page
    const rowH = 24;
    const headerH = 32;
    const bottomSafe = 48;
    const tableLeft = M;
    const tableW = W - 2 * M;
    const colQtyW = 48;
    const colUnitW = 112;
    const colLineW = 112;
    const colItemW = tableW - colQtyW - colUnitW - colLineW;
    const xItem = tableLeft;
    const xQty = tableLeft + colItemW;
    const xUnit = xQty + colQtyW;
    const xLine = xUnit + colUnitW;

    const topFirst = (firstTopY != null) ? firstTopY : 48;
    const topCont = 48;
    const maxFirst = Math.max(6, Math.floor((H - topFirst - bottomSafe - headerH - 36) / rowH));
    const maxCont = Math.max(12, Math.floor((H - topCont - bottomSafe - headerH - 36) / rowH));

    const chunks = [];
    let i = 0;
    let first = true;
    while (i < list.length) {
      const n = first ? maxFirst : maxCont;
      chunks.push(list.slice(i, i + n));
      i += n;
      first = false;
    }
    if (!chunks.length) chunks.push([]);

    const grandTotal = list.reduce((s, p) => s + lineTotal(p), 0);
    let pageNo = startPageNo;

    function drawTableChunk(chunk, topY, isLast) {
      let ty = topY;
      const tableStartY = ty;

      setFill(NAVY);
      doc.rect(tableLeft, ty, tableW, headerH, 'F');
      setCol(WHITE); doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
      const hy = ty + 14;
      doc.text('Item', xItem + 10, hy + 6);
      doc.text('Qty', xQty + colQtyW / 2, hy + 6, { align: 'center' });
      doc.text('Original Unit', xUnit + colUnitW - 8, hy, { align: 'right' });
      doc.text('Price', xUnit + colUnitW - 8, hy + 11, { align: 'right' });
      doc.text('Line Total', xLine + colLineW - 8, hy + 6, { align: 'right' });
      ty += headerH;

      chunk.forEach((p, ri) => {
        if (ri % 2 === 1) {
          setFill([242, 244, 247]);
          doc.rect(tableLeft, ty, tableW, rowH, 'F');
        } else {
          setFill(WHITE);
          doc.rect(tableLeft, ty, tableW, rowH, 'F');
        }
        setDraw([210, 215, 222]);
        doc.setLineWidth(0.5);
        doc.line(tableLeft, ty + rowH, tableLeft + tableW, ty + rowH);
        doc.line(xQty, ty, xQty, ty + rowH);
        doc.line(xUnit, ty, xUnit, ty + rowH);
        doc.line(xLine, ty, xLine, ty + rowH);

        const qty = lineQty(p);
        const unit = lineUnit(p);
        const total = unit * qty;
        const name = String(p.name || 'Item');
        setCol([30, 35, 42]); doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
        const maxNameW = colItemW - 18;
        let displayName = name;
        while (doc.getTextWidth(displayName) > maxNameW && displayName.length > 5) {
          displayName = displayName.slice(0, -2);
        }
        if (displayName !== name) displayName = displayName.replace(/\s+\S*$/, '') + '…';
        const textY = ty + 16;
        doc.text(displayName, xItem + 10, textY);
        doc.text(String(qty), xQty + colQtyW / 2, textY, { align: 'center' });
        doc.text(formatNairaPlain(unit), xUnit + colUnitW - 8, textY, { align: 'right' });
        doc.setFont('helvetica', 'bold');
        doc.text(formatNairaPlain(total), xLine + colLineW - 8, textY, { align: 'right' });
        ty += rowH;
      });

      setDraw([180, 186, 196]);
      doc.setLineWidth(0.8);
      doc.rect(tableLeft, tableStartY, tableW, headerH + chunk.length * rowH);

      if (isLast) {
        ty += 10;
        setFill(NAVY);
        doc.rect(tableLeft, ty, tableW, 28, 'F');
        setCol(WHITE); doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
        doc.text('TOTAL', xItem + 10, ty + 18);
        doc.text(formatNairaPlain(grandTotal), xLine + colLineW - 8, ty + 18, { align: 'right' });
      } else {
        setCol([100, 110, 120]); doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
        doc.text('Continued on next page…', M, ty + 18);
      }
    }

    chunks.forEach((chunk, ci) => {
      if (ci === 0 && firstTopY != null) {
        // First page already started by caller (offer drawn) — only table
        drawTableChunk(chunk, topFirst, ci === chunks.length - 1);
      } else {
        if (!(ci === 0 && firstTopY != null)) {
          if (ci > 0 || firstTopY == null) doc.addPage();
        }
        setFill(CREAM); doc.rect(0, 0, W, H, 'F');
        drawTableChunk(chunk, ci === 0 && firstTopY == null ? topFirst : topCont, ci === chunks.length - 1);
      }
      footer(pageNo, totalPagesGuess);
      pageNo++;
    });
    return pageNo;
  }

  const packs = isUltraSummary ? [] : packMachines(products);
  const estUltraPages = Math.max(1, Math.ceil(products.length / 24));
  const estSummaryPages = isSimpleSummary
    ? 0
    : isUltraSummary
      ? estUltraPages
      : Math.max(1, Math.ceil(products.length / (isList ? 18 : 14)));
  const catPages = packs.length + estSummaryPages;
  const totalPages = 2 + catPages + 2;

  // ---- COVER ----
  // Full-page navy (must fill entire page so nothing sits on white)
  setFill(NAVY); doc.rect(0, 0, W, H, 'F');
  setDraw([56, 77, 102]); doc.setLineWidth(0.75);
  doc.rect(26, 26, W - 52, H - 52);
  const nameParts = (co.name || 'MEDICANO RESOURCES LIMITED').split(/\s+/);
  const main = (nameParts[0] || 'MEDICANO').toUpperCase();
  const sub = (nameParts.slice(1).join(' ') || 'RESOURCES LIMITED').toUpperCase();
  // Centered brand block
  setCol(CREAM); doc.setFont('helvetica', 'bold'); doc.setFontSize(36);
  doc.text(main, W / 2, H * 0.40, { align: 'center' });
  setCol(GOLDSOFT); doc.setFont('helvetica', 'normal'); doc.setFontSize(13);
  doc.text(sub, W / 2, H * 0.40 + 24, { align: 'center' });
  setDraw(GOLD); doc.setLineWidth(1.5);
  doc.line(W / 2 - 30, H * 0.40 + 42, W / 2 + 30, H * 0.40 + 42);
  setCol(CREAM); doc.setFontSize(15); doc.text('Medical Equipment Proposal', W / 2, H * 0.40 + 68, { align: 'center' });
  setCol([184, 191, 204]); doc.setFontSize(11.5);
  doc.text('Prepared for ' + forClient, W / 2, H * 0.40 + 92, { align: 'center' });
  doc.text(dateStr, W / 2, H * 0.40 + 110, { align: 'center' });

  // Footer block — measure first, place fully inside navy (above bottom margin)
  const footSize = 9;
  const footLead = 11;
  const addrLines = wrap(co.address || '', footSize, W - 2 * M - 100);
  const telLine = (co.phone1 || co.phone2)
    ? 'Tel: ' + [co.phone1, co.phone2].filter(Boolean).join('  |  ')
    : '';
  const emailLine = co.email ? 'Email: ' + co.email : '';
  const footLines = [...addrLines];
  if (telLine) footLines.push(telLine);
  if (emailLine) footLines.push(emailLine);
  const footBlockH = footLines.length * footLead + 16; // + space under divider
  const footBottom = 48; // stay above page edge
  const dividerY = footBottom + footBlockH;
  setDraw([56, 77, 102]); doc.setLineWidth(0.75);
  doc.line(M, dividerY, W - M, dividerY);
  // Brighter text so it stays readable on navy
  setCol([220, 226, 234]); doc.setFont('helvetica', 'normal'); doc.setFontSize(footSize);
  let by = dividerY + 14;
  footLines.forEach(ln => {
    doc.text(ln, M, by);
    by += footLead;
  });
  setCol(GOLDSOFT); doc.setFont('helvetica', 'normal'); doc.setFontSize(16);
  doc.text('01 / ' + String(totalPages).padStart(2, '0'), W - M, footBottom + 4, { align: 'right' });

  // ---- ABOUT ----
  doc.addPage();
  setFill(CREAM); doc.rect(0, 0, W, H, 'F');
  const panelW = 170;
  setFill(NAVY); doc.rect(W - panelW, 0, panelW, H, 'F');
  setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
  doc.text('PRECISION', W - panelW + 18, 90);
  setCol(CREAM2); doc.setFontSize(10);
  doc.text('EQUIPMENT, BUILT', W - panelW + 18, 110);
  doc.text('FOR AFRICAN', W - panelW + 18, 128);
  doc.text('HEALTHCARE.', W - panelW + 18, 146);
  // No phone/email at bottom-right — contact is only in the cards below

  setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(9.5);
  doc.text('COMPANY PROFILE', M, 58);
  setCol(NAVY); doc.setFontSize(20);
  doc.text('WELCOME TO MEDICANO', M, 88);
  doc.text('RESOURCES', M, 112);
  setDraw(GOLD); doc.setLineWidth(1.5); doc.line(M, 128, M + 54, 128);
  const welcome = "Incorporated in 2010, we are a multispecialty leading player in the marketing and distribution of Turnkey Medical Equipment and Technology in the Nigerian market with core expertise in Endoscopic equipment, Ear, Nose and Throat Equipment, Cranio and Oral Maxillofacial, Imaging Equipment (MRI, CT, X-Ray, Ultrasound etc), Hospital Furnishing, Intensive Care Unit Solutions, Neonatal & Pediatrics' solutions as well as a wide Theatre instruments portfolio and equipment amongst other things.\n\nWe offer complete integrated medical solutions to our clients which has endeared us to their hearts. We say integrated because we proffer advisory services, through our seasoned and well trained technical personnel, from our first contact with the client all the way to our after sales service long after the sales have been made. Also, our tradition of excellent service delivery by our experienced and enthusiastic employees, has continued to differentiate us from others in the health care industry.";
  setCol([55, 56, 60]); doc.setFont('helvetica', 'normal'); doc.setFontSize(BODY);
  let ay = 152;
  const maxAboutW = W - panelW - M - 28;
  welcome.split('\n').forEach(para => {
    if (!para.trim()) { ay += 10; return; }
    wrap(para.trim(), BODY, maxAboutW).forEach(ln => { doc.text(ln, M, ay); ay += BODY_LEAD; });
    ay += 8;
  });
  // Detail cards: address / phone / email
  ay += 16;
  const cardGap = 12;
  const leftW = W - panelW - M - 28;
  const cardW3 = (leftW - cardGap * 2) / 3;
  const cardH = 150;
  const cards = [
    ['REGISTERED OFFICE', co.address || '', 'text'],
    ['DIRECT LINE', [co.phone1, co.phone2].filter(Boolean).join('\n'), 'text'],
    ['CORRESPONDENCE', co.email || '', 'email']
  ];
  cards.forEach((card, i) => {
    const cx = M + i * (cardW3 + cardGap);
    setFill(WHITE); setDraw(LINE); doc.setLineWidth(0.75);
    doc.roundedRect(cx, ay, cardW3, cardH, 6, 6, 'FD');
    // Gold accent with clear space before the label and address
    setDraw(GOLD); doc.setLineWidth(1.6); doc.line(cx + 12, ay + 18, cx + 34, ay + 18);
    setCol(GRAY); doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
    doc.text(card[0], cx + 12, ay + 40);
    setCol(NAVY); doc.setFont('helvetica', 'normal'); doc.setFontSize(BODY);
    let vy = ay + 60;
    const maxTextW = cardW3 - 24;
    if (card[2] === 'email' && card[1]) {
      const email = String(card[1]).trim();
      const lines = wrap(email, BODY, maxTextW);
      lines.forEach((ln, li) => {
        // Clickable mailto link (jsPDF)
        try {
          if (typeof doc.textWithLink === 'function') {
            setCol([11, 90, 160]);
            doc.textWithLink(ln, cx + 12, vy, { url: 'mailto:' + email });
          } else {
            setCol([11, 90, 160]);
            doc.text(ln, cx + 12, vy);
            const tw = doc.getTextWidth(ln);
            doc.link(cx + 12, vy - BODY + 2, tw, BODY + 2, { url: 'mailto:' + email });
          }
        } catch (e) {
          setCol([11, 90, 160]);
          doc.text(ln, cx + 12, vy);
        }
        // Underline to show it is a link
        setDraw([11, 90, 160]); doc.setLineWidth(0.6);
        const tw2 = doc.getTextWidth(ln);
        doc.line(cx + 12, vy + 2, cx + 12 + tw2, vy + 2);
        vy += BODY_LEAD - 2;
      });
    } else {
      wrap(card[1], BODY, maxTextW).slice(0, 6).forEach(ln => {
        doc.text(ln, cx + 12, vy); vy += BODY_LEAD - 2;
      });
    }
  });
  // Tagline after contact cards, before page footer
  const tagY = Math.min(ay + cardH + 28, H - 56);
  setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(12);
  doc.text('...Making a Habit of Excellence', M, tagY);
  footer(2, totalPages);

  // ---- CATALOGUE / ULTRA TABLE ----
  let pageNo = 3;
  function drawSimpleTotal(x, y, w) {
    const grand = products.reduce((s, p) => s + lineTotal(p), 0);
    const boxH = 72;
    setFill(NAVY);
    doc.roundedRect(x, y, w, boxH, 10, 10, 'F');
    setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
    doc.text('TOTAL PROPOSAL VALUE', x + 20, y + 26);
    setCol(CREAM); doc.setFont('helvetica', 'bold'); doc.setFontSize(18);
    doc.text(formatNairaPlain(grand), x + w - 20, y + 30, { align: 'right' });
    setCol([160, 170, 185]); doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
    doc.text(products.length + (products.length === 1 ? ' item' : ' items') + ' · indicative pricing in Naira', x + 20, y + 52);
    return boxH;
  }

  const offerText = 'Please find below herewith our OFFER for equipping your hospital with our PREMIUM MEDICAL EQUIPMENT that assures of quality and long-lasting use. We look forward to your final review to enable us proceed on the arrangement.';

  if (isUltraSummary) {
    // Ultra: offer text, then table only (no catalogue cards, no "Price Summary" heading)
    doc.addPage();
    setFill(CREAM); doc.rect(0, 0, W, H, 'F');
    setCol(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(20);
    doc.text('Equipment Catalogue', M, 58);
    setDraw(GOLD); doc.setLineWidth(1.4); doc.line(M, 74, M + 54, 74);
    setCol([55, 56, 60]); doc.setFont('helvetica', 'normal'); doc.setFontSize(BODY);
    let oy = 74 + 20;
    wrap(offerText, BODY, W - 2 * M).forEach(ln => { doc.text(ln, M, oy); oy += BODY_LEAD; });
    const tableTop = oy + 18;
    pageNo = drawUltraSummaryPages(products, pageNo, totalPages, tableTop);
  } else {
    packs.forEach((pack, pi) => {
      doc.addPage();
      setFill(CREAM); doc.rect(0, 0, W, H, 'F');
      setCol(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(20);
      doc.text('Equipment Catalogue', M, 58);
      let topLimit = 100;
      if (pi > 0) {
        setCol(GRAY); doc.setFont('helvetica', 'normal'); doc.setFontSize(BODY);
        doc.text('continued', W - M, 58, { align: 'right' });
        setDraw(GOLD); doc.setLineWidth(1.4); doc.line(M, 74, M + 54, 74);
        topLimit = 92;
      } else {
        setDraw(GOLD); doc.setLineWidth(1.4); doc.line(M, 74, M + 54, 74);
        setCol([55, 56, 60]); doc.setFont('helvetica', 'normal'); doc.setFontSize(BODY);
        let oy = 74 + 20;
        wrap(offerText, BODY, W - 2 * M).forEach(ln => { doc.text(ln, M, oy); oy += BODY_LEAD; });
        topLimit = oy + 18;
      }

      const gap = pack.gap != null ? pack.gap : (isList ? 6 : 12);
      const isLastPack = pi === packs.length - 1;
      const simpleBoxH = 72;
      const simpleGap = 16;
      const reserveSimple = (isSimpleSummary && isLastPack) ? (simpleBoxH + simpleGap) : 0;
      const totalH = pack.items.reduce((s, it) => s + it.h, 0) + gap * Math.max(0, pack.items.length - 1);
      const bottomLimit = 50 + reserveSimple;
      const area = H - topLimit - bottomLimit;
      let yTop = topLimit + Math.max(0, (area - totalH) / 2);
      if (isList && pack.items.length >= 8) yTop = topLimit;
      if (reserveSimple && yTop + totalH + simpleGap + simpleBoxH > H - 50) {
        yTop = topLimit;
      }
      const cardW = W - 2 * M;
      pack.items.forEach(it => {
        drawCard(it.p, M, yTop, cardW, it.h);
        yTop += it.h + gap;
      });
      if (isSimpleSummary && isLastPack) {
        let sy = yTop + simpleGap;
        if (sy + simpleBoxH > H - 48) {
          sy = Math.max(topLimit, H - 48 - simpleBoxH);
        }
        drawSimpleTotal(M, sy, cardW);
      }
      footer(pageNo, totalPages);
      pageNo++;
    });

    if (!isSimpleSummary) {
      doc.addPage();
      pageNo = drawSummaryPages(products, pageNo, totalPages);
    }
  }

  // ---- TERMS (always ONE page — auto-fit spacing so nothing spills) ----
  let termHeadSize = 14;
  let termBodySize = 12.5;
  let termBodyLead = 17;
  let termGap = 16;
  let termHeadLead = 18;
  const termsList = (data.terms && data.terms.length) ? data.terms : DEFAULT_DATA.terms;

  function measureTermsBlock(list, bodySize, bodyLead, headLead, gap) {
    let h = 0;
    list.forEach((t) => {
      const val = t.body || t[1] || '';
      h += headLead;
      h += wrap(val, bodySize, W - 2 * M).length * bodyLead;
      h += gap;
    });
    return h;
  }

  doc.addPage();
  setFill(CREAM); doc.rect(0, 0, W, H, 'F');
  setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
  doc.text('COMMERCIAL TERMS', M, 58);
  setCol(NAVY); doc.setFontSize(22);
  doc.text('Terms and Conditions', M, 86);
  setDraw(GOLD); doc.setLineWidth(1.5); doc.line(M, 102, M + 54, 102);

  const usableTop = 122;
  const usableBottom = H - 48;
  const usableH = usableBottom - usableTop;

  let blockH = measureTermsBlock(termsList, termBodySize, termBodyLead, termHeadLead, termGap);
  let guard = 0;
  while (blockH > usableH && guard < 14) {
    termBodyLead = Math.max(13, termBodyLead - 0.5);
    termGap = Math.max(7, termGap - 0.8);
    termHeadLead = Math.max(14, termHeadLead - 0.4);
    if (guard > 5) {
      termBodySize = Math.max(10.5, termBodySize - 0.25);
      termHeadSize = Math.max(12, termHeadSize - 0.25);
    }
    blockH = measureTermsBlock(termsList, termBodySize, termBodyLead, termHeadLead, termGap);
    guard++;
  }

  // Vertically center the full T&C group on this single page
  let ty = usableTop + Math.max(0, (usableH - blockH) / 2);

  termsList.forEach((t) => {
    const lab = t.title || t[0] || '';
    const val = t.body || t[1] || '';
    const lines = wrap(val, termBodySize, W - 2 * M);
    setCol(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(termHeadSize);
    doc.text(String(lab).toUpperCase(), M, ty); ty += termHeadLead;
    setCol([50, 51, 55]); doc.setFont('helvetica', 'normal'); doc.setFontSize(termBodySize);
    lines.forEach(ln => { doc.text(ln, M, ty); ty += termBodyLead; });
    ty += termGap;
  });
  footer(pageNo, totalPages);
  pageNo++;

  // ---- CLOSING (same font units as T&C) ----
  doc.addPage();
  setFill(CREAM); doc.rect(0, 0, W, H, 'F');
  setCol(GOLD); doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
  doc.text('NEXT STEPS', M, 58);
  setDraw(GOLD); doc.setLineWidth(1.5); doc.line(M, 74, M + 54, 74);

  // Measure closing block then center vertically
  const closeLines1 = wrap('Thank you for doing business with us while we look forward to receiving the confirmation of your order.', termBodySize, W - 2 * M - 40);
  const closeLines2 = wrap('For further information or any clarification, please contact us the undersigned on Tel. 09099995426 or call Francis on 08023203522. E-mail: enquiries@medicanoresources.com', termBodySize, W - 2 * M - 40);
  const closeBlockH = closeLines1.length * termBodyLead + 14 + closeLines2.length * termBodyLead + 28 + termBodyLead + 36 + termHeadLead + 40 + termBodyLead;
  let cy = 96 + Math.max(0, (H - 96 - 50 - closeBlockH) / 2);

  setCol(INK); doc.setFont('helvetica', 'normal'); doc.setFontSize(termBodySize);
  closeLines1.forEach(ln => { doc.text(ln, M, cy); cy += termBodyLead; });
  cy += 14;
  closeLines2.forEach(ln => { doc.text(ln, M, cy); cy += termBodyLead; });
  cy += 28;
  doc.setFontSize(termBodySize); doc.text('Yours faithfully,', M, cy);
  cy += 36;
  setCol(NAVY); doc.setFont('helvetica', 'bold'); doc.setFontSize(termHeadSize);
  doc.text('FOR: ' + (co.name || 'Medicano Resources Limited'), M, cy);
  cy += 40;
  doc.setFontSize(termHeadSize); doc.text('Francis Opara', M, cy);
  setCol(GRAY); doc.setFont('helvetica', 'normal'); doc.setFontSize(termBodySize);
  doc.text('CEO', M, cy + 18);
  footer(pageNo, totalPages);

  // Filename leads with client/hospital name
  const sanitize = (s, max) => String(s || '')
    .replace(/[\\/:*?"<>|]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max || 50);
  const clientName = sanitize(forClient, 50) || 'Client';
  const docTitle = sanitize(title, 40) || 'Presentation';
  doc.save(clientName + ' - ' + docTitle + '.pdf');
}

function escHtml(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// -------------------- Dark Mode --------------------
function toggleDarkMode() {
  const html = document.documentElement;
  const isDark = html.classList.toggle('dark');
  localStorage.setItem('medicano_dark', isDark ? '1' : '0');
  const btn = document.getElementById('dark-toggle');
  if (btn) btn.textContent = isDark ? '☀️' : '🌙';
}

function initDarkMode() {
  const saved = localStorage.getItem('medicano_dark');
  if (saved === '1' || (!saved && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
    document.documentElement.classList.add('dark');
    const btn = document.getElementById('dark-toggle');
    if (btn) btn.textContent = '☀️';
  }
}

// -------------------- Quote Product Picker --------------------
function toggleQuoteEquipPanel() {
  const panel = document.getElementById('quote-equip-panel');
  if (!panel) return;
  panel.classList.toggle('collapsed');
}

function renderQuoteProductPicker() {
  const search = (document.getElementById('quote-product-search')?.value || '').toLowerCase();
  const container = document.getElementById('quote-product-picker');
  if (!container) return;

  const active = data.products.filter(p => p.active);
  const list = active.filter(p =>
    !search ||
    p.name.toLowerCase().includes(search) ||
    p.sku.toLowerCase().includes(search) ||
    (p.category || '').toLowerCase().includes(search) ||
    (p.brand || '').toLowerCase().includes(search)
  );

  if (list.length === 0) {
    container.innerHTML = '<p class="p-3 text-slate-400 text-center">No items found</p>';
    return;
  }

  container.innerHTML = list.map(p => {
    const ngn = toNGN(p.price, p.currency);
    const desc = (p.description || '').trim();
    const shortDesc = desc ? (desc.length > 90 ? desc.slice(0, 87) + '…' : desc) : '';
    return `<div class="qp-row">
      <input type="checkbox" class="qp-check rounded" value="${p.id}" data-sku="${escHtml(p.sku)}" />
      <div class="qp-meta">
        <p class="font-medium">${escHtml(p.name)}</p>
        <p class="text-xs text-slate-500">${escHtml(p.sku)} • ${escHtml(p.category || '')} • ${formatNGN(ngn)}</p>
        ${shortDesc ? `<p class="text-xs text-slate-400 mt-0.5">${escHtml(shortDesc)}</p>` : ''}
      </div>
      <div class="qp-units">
        <span class="text-xs text-slate-400">Units</span>
        <input type="number" min="1" step="1" value="1" class="qp-qty" data-for="${p.id}" onclick="event.stopPropagation()" />
      </div>
    </div>`;
  }).join('');
}

function selectAllQuoteProducts(checked) {
  document.querySelectorAll('#quote-product-picker .qp-check').forEach(cb => {
    cb.checked = checked;
  });
}

function addSelectedProductsToQuote() {
  const checked = [...document.querySelectorAll('#quote-product-picker .qp-check:checked')];
  if (checked.length === 0) {
    alert('Please select at least one equipment item.');
    return;
  }

  // Map existing product rows to update qty instead of skipping
  const existingRows = {};
  document.querySelectorAll('#quote-items-list .line-card').forEach(row => {
    const sel = row.querySelector('.qi-product');
    if (sel && sel.value) existingRows[sel.value] = row;
  });

  let added = 0;
  let updated = 0;
  checked.forEach(cb => {
    const id = cb.value;
    const qtyInput = document.querySelector('#quote-product-picker .qp-qty[data-for="' + id + '"]');
    const qty = Math.max(1, parseFloat(qtyInput && qtyInput.value) || 1);
    if (existingRows[id]) {
      const qEl = existingRows[id].querySelector('.qi-qty');
      if (qEl) qEl.value = qty;
      updated++;
    } else {
      addQuoteItemRow({ productId: id, qty: qty });
      added++;
    }
  });

  selectAllQuoteProducts(false);
  if (document.getElementById('quote-product-search')) {
    document.getElementById('quote-product-search').value = '';
    renderQuoteProductPicker();
  }

  recalcQuote();
  // Collapse picker after adding so user focuses on units in line items
  const panel = document.getElementById('quote-equip-panel');
  if (panel && (added || updated)) panel.classList.add('collapsed');

  if (!added && !updated) {
    alert('Nothing was added.');
  } else {
    const msg = [];
    if (added) msg.push(added + ' added');
    if (updated) msg.push(updated + ' qty updated');
    // soft feedback via item count is enough
  }
}

// -------------------- UI helpers --------------------
function closeModal(id) {
  document.getElementById(id).classList.add('hidden');
}



// -------------------- Transaction Reports --------------------

const REPORT_FILTERS_KEY = 'medicano_report_filters_v1';



// -------------------- Manual / editable report table rows --------------------
function ensureReportRows() {
  if (!Array.isArray(data.reportTableRows)) data.reportTableRows = [];
  // migrate old customReports once
  if (Array.isArray(data.customReports) && data.customReports.length && !data._migratedCustomReports) {
    data.customReports.forEach(function (e) {
      data.reportTableRows.push({
        id: e.id || uid(),
        date: e.date || '',
        typeLabel: 'Custom',
        clientId: e.clientId || '',
        clientName: '',
        ref: e.invoiceNumber || '',
        title: e.name || '',
        detail: e.notes || e.name || '',
        amount: Number(e.lineNgn) || 0,
        invoiceId: e.invoiceId || null,
        createdAt: e.createdAt || new Date().toISOString()
      });
    });
    data._migratedCustomReports = true;
  }
}

function openReportRowEditor(id) {
  ensureReportRows();
  const modal = document.getElementById('modal-report-row');
  if (!modal) return;
  const row = id ? (data.reportTableRows || []).find(function (r) { return r.id === id; }) : null;
  document.getElementById('report-row-modal-title').textContent = row ? 'Edit table row' : 'Add table row';
  document.getElementById('rr-id').value = row ? row.id : '';
  document.getElementById('rr-date').value = row ? (row.date || '') : new Date().toISOString().slice(0, 10);
  document.getElementById('rr-type').value = row ? (row.typeLabel || 'Custom') : 'Custom';
  document.getElementById('rr-ref').value = row ? (row.ref || '') : '';
  document.getElementById('rr-title').value = row ? (row.title || '') : '';
  const del = document.getElementById('rr-delete-btn');
  if (del) del.classList.toggle('hidden', !row);

  const clientSel = document.getElementById('rr-client');
  if (clientSel) {
    clientSel.innerHTML = '<option value="">— No client —</option>' +
      (data.clients || []).slice().sort(function (a, b) { return (a.name || '').localeCompare(b.name || ''); }).map(function (c) {
        return '<option value="' + c.id + '"' + (row && row.clientId === c.id ? ' selected' : '') + '>' + escHtml(c.name) + '</option>';
      }).join('');
  }

  // Line items: migrate single detail/amount into one item if needed
  let items = [];
  if (row && Array.isArray(row.items) && row.items.length) {
    items = row.items.map(function (it) {
      return {
        name: it.name || '',
        qty: Number(it.qty) || 1,
        unitPrice: Number(it.unitPrice) || 0
      };
    });
  } else if (row && (row.detail || row.amount)) {
    items = [{ name: row.detail || row.title || 'Item', qty: 1, unitPrice: Number(row.amount) || 0 }];
  } else {
    items = [{ name: '', qty: 1, unitPrice: 0 }];
  }
  window._rrItems = items;
  renderReportRowItemsEditor();
  modal.classList.remove('hidden');
}

function renderReportRowItemsEditor() {
  const list = document.getElementById('rr-items-list');
  if (!list) return;
  if (!Array.isArray(window._rrItems) || !window._rrItems.length) {
    window._rrItems = [{ name: '', qty: 1, unitPrice: 0 }];
  }
  list.innerHTML = window._rrItems.map(function (it, i) {
    return '<div class="rr-item-row" data-i="' + i + '">' +
      '<input type="text" class="settings-input rr-item-name" placeholder="Item name" value="' + escHtml(it.name || '') + '" oninput="updateReportRowItem(' + i + ',\'name\',this.value)" />' +
      '<input type="number" min="1" step="1" class="settings-input rr-item-qty" placeholder="Qty" value="' + (Number(it.qty) || 1) + '" oninput="updateReportRowItem(' + i + ',\'qty\',this.value)" />' +
      '<input type="number" min="0" step="0.01" class="settings-input rr-item-price" placeholder="Unit ₦" value="' + (Number(it.unitPrice) || 0) + '" oninput="updateReportRowItem(' + i + ',\'unitPrice\',this.value)" />' +
      '<button type="button" class="rr-item-remove" onclick="removeReportRowItemLine(' + i + ')" title="Remove">✕</button>' +
      '</div>';
  }).join('');
  recalcReportRowItemsTotal();
}

function updateReportRowItem(i, field, val) {
  if (!window._rrItems || !window._rrItems[i]) return;
  if (field === 'name') window._rrItems[i].name = val;
  else if (field === 'qty') window._rrItems[i].qty = Math.max(1, parseFloat(val) || 1);
  else if (field === 'unitPrice') window._rrItems[i].unitPrice = parseFloat(val) || 0;
  recalcReportRowItemsTotal();
}

function addReportRowItemLine() {
  if (!window._rrItems) window._rrItems = [];
  window._rrItems.push({ name: '', qty: 1, unitPrice: 0 });
  renderReportRowItemsEditor();
}

function removeReportRowItemLine(i) {
  if (!window._rrItems) return;
  window._rrItems.splice(i, 1);
  if (!window._rrItems.length) window._rrItems.push({ name: '', qty: 1, unitPrice: 0 });
  renderReportRowItemsEditor();
}

function recalcReportRowItemsTotal() {
  const items = window._rrItems || [];
  let total = 0;
  items.forEach(function (it) {
    total += (Number(it.qty) || 1) * (Number(it.unitPrice) || 0);
  });
  const el = document.getElementById('rr-items-total');
  if (el) el.textContent = formatNGN(total);
  return total;
}

function closeReportRowEditor() {
  const modal = document.getElementById('modal-report-row');
  if (modal) modal.classList.add('hidden');
}

function saveReportTableRow() {
  ensureReportRows();
  const idEl = document.getElementById('rr-id');
  const id = (idEl && idEl.value) || '';
  const clientId = (document.getElementById('rr-client') && document.getElementById('rr-client').value) || '';
  const client = clientId ? getClient(clientId) : null;
  const dateVal = (document.getElementById('rr-date') && document.getElementById('rr-date').value) || new Date().toISOString().slice(0, 10);
  const titleVal = ((document.getElementById('rr-title') && document.getElementById('rr-title').value) || '').trim();
  const typeVal = ((document.getElementById('rr-type') && document.getElementById('rr-type').value) || 'Custom').trim() || 'Custom';

  const rawItems = (window._rrItems || []).map(function (it) {
    return {
      name: (it.name || '').trim(),
      qty: Math.max(1, Number(it.qty) || 1),
      unitPrice: Number(it.unitPrice) || 0,
      lineNgn: Math.max(1, Number(it.qty) || 1) * (Number(it.unitPrice) || 0)
    };
  }).filter(function (it) { return it.name; });

  if (!rawItems.length) {
    alert('Add at least one line item with a name.');
    return;
  }
  const amount = rawItems.reduce(function (s, it) { return s + it.lineNgn; }, 0);
  const detailVal = rawItems.map(function (it) {
    return it.name + (it.qty > 1 ? ' ×' + it.qty : '');
  }).join(', ');

  const entry = {
    id: id || uid(),
    date: dateVal,
    typeLabel: typeVal,
    clientId: clientId,
    clientName: client ? client.name : '—',
    ref: ((document.getElementById('rr-ref') && document.getElementById('rr-ref').value) || '').trim(),
    title: titleVal,
    detail: detailVal,
    items: rawItems,
    amount: amount,
    invoiceId: null,
    updatedAt: new Date().toISOString()
  };
  if (id) {
    const idx = data.reportTableRows.findIndex(function (r) { return r.id === id; });
    if (idx >= 0) {
      entry.invoiceId = data.reportTableRows[idx].invoiceId || null;
      entry.createdAt = data.reportTableRows[idx].createdAt;
      data.reportTableRows[idx] = entry;
    } else {
      entry.createdAt = new Date().toISOString();
      data.reportTableRows.unshift(entry);
    }
  } else {
    entry.createdAt = new Date().toISOString();
    data.reportTableRows.unshift(entry);
  }
  if (typeof bindWindowData === 'function') bindWindowData();
  saveData();

  const fromEl = document.getElementById('report-date-from');
  const toEl = document.getElementById('report-date-to');
  if (fromEl && fromEl.value && dateVal && dateVal < fromEl.value) fromEl.value = dateVal;
  if (toEl && toEl.value && dateVal && dateVal > toEl.value) toEl.value = dateVal;
  const typeEl = document.getElementById('report-type');
  if (typeEl && typeEl.value === 'payments') typeEl.value = 'all';

  if (clientId) {
    const cb = document.querySelector('#report-client-list input[type=checkbox][value="' + clientId + '"]');
    if (cb) {
      const anyChecked = document.querySelectorAll('#report-client-list input[type=checkbox]:checked').length > 0;
      if (anyChecked) {
        cb.checked = true;
        const row = cb.closest('.select-row');
        if (row) row.classList.add('is-selected');
      }
    }
  }

  closeReportRowEditor();
  if (typeof renderTransactionReport === 'function') renderTransactionReport();
}

function deleteReportTableRow() {
  const id = document.getElementById('rr-id').value;
  if (!id) return;
  if (!confirm('Delete this table row?')) return;
  ensureReportRows();
  data.reportTableRows = data.reportTableRows.filter(function (r) { return r.id !== id; });
  saveData();
  closeReportRowEditor();
  renderTransactionReport();
}

function addSelectedReportRowsToInvoice() {
  ensureReportRows();
  const ids = [...document.querySelectorAll('.rr-row-check:checked')].map(function (cb) { return cb.value; });
  if (!ids.length) {
    alert('Select one or more custom table rows first.');
    return;
  }
  const entries = (data.reportTableRows || []).filter(function (r) { return ids.indexOf(r.id) >= 0 && !r.invoiceId; });
  if (!entries.length) {
    alert('No unbilled custom rows selected.');
    return;
  }
  const clientIds = [...new Set(entries.map(function (e) { return e.clientId; }).filter(Boolean))];
  if (clientIds.length > 1) {
    alert('Select rows for one client only.');
    return;
  }
  if (!clientIds.length) {
    alert('Custom rows need a client before creating an invoice.');
    return;
  }
  const clientId = clientIds[0];
  const client = getClient(clientId);
  const items = [];
  entries.forEach(function (e) {
    if (Array.isArray(e.items) && e.items.length) {
      e.items.forEach(function (it) {
        items.push({
          productId: '',
          name: it.name || e.title || 'Item',
          qty: Number(it.qty) || 1,
          unitNgn: Number(it.unitPrice) || 0,
          lineNgn: Number(it.lineNgn) || ((Number(it.qty) || 1) * (Number(it.unitPrice) || 0)),
          reportRowId: e.id
        });
      });
    } else {
      items.push({
        productId: '',
        name: e.title || e.detail || e.typeLabel || 'Report line',
        qty: 1,
        unitNgn: Number(e.amount) || 0,
        lineNgn: Number(e.amount) || 0,
        reportRowId: e.id
      });
    }
  });
  const sub = items.reduce(function (s, it) { return s + (Number(it.lineNgn) || 0); }, 0);
  const inv = {
    id: uid(),
    invoiceNumber: nextInvoiceNumber(),
    clientId: clientId,
    title: 'From report table — ' + (client ? client.name : 'Client'),
    status: 'unpaid',
    date: new Date().toISOString().slice(0, 10),
    dueDate: '',
    notes: 'Created from custom rows on Reports.',
    showFooter: true,
    discount: 0,
    items: items,
    subtotalNgn: sub,
    totalNgn: sub,
    payments: [],
    amountPaid: 0,
    docType: 'tax',
    stockDeducted: false,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };
  if (!data.invoices) data.invoices = [];
  data.invoices.unshift(inv);
  entries.forEach(function (e) { e.invoiceId = inv.id; e.ref = inv.invoiceNumber; });
  saveData();
  renderTransactionReport();
  alert('Invoice ' + inv.invoiceNumber + ' created.');
  if (typeof editInvoice === 'function') editInvoice(inv.id);
  else navigate('invoices');
}

function collectLedgerRows({ from, to, clientIds, method, type } = {}) {
  const rows = [];
  const clientSet = (clientIds && clientIds.length) ? new Set(clientIds) : null;
  const t = type || 'payments';
  // Custom (manual) rows always appear except when user picks pure Payments or pure Invoices
  const wantPay = t === 'payments' || t === 'both' || t === 'all';
  const wantInv = t === 'invoices' || t === 'both' || t === 'all';
  const wantCustom = t === 'custom' || t === 'all' || t === 'both' || t === 'payments' || t === 'invoices';
  // When filter is "custom", only manual rows
  const onlyCustom = t === 'custom';
  const doPay = wantPay && !onlyCustom;
  const doInv = wantInv && !onlyCustom;

  if (doPay || doInv) {
    (data.invoices || []).forEach(inv => {
      if (clientSet && !clientSet.has(inv.clientId)) return;
      const client = getClient(inv.clientId);
      const clientName = client ? client.name : (inv.clientName || '—');

      if (doInv) {
        const d = (inv.date || (inv.createdAt || '').slice(0, 10) || '');
        if (!(from && d && d < from) && !(to && d && d > to)) {
          rows.push({
            kind: 'invoice',
            id: inv.id,
            date: d || '—',
            clientId: inv.clientId || '',
            clientName,
            ref: inv.invoiceNumber || '—',
            title: inv.title || '',
            method: (inv.status || '').toString(),
            note: 'Invoice issued',
            amount: Number(inv.totalNGN != null ? inv.totalNGN : inv.totalNgn) || 0,
            editable: false
          });
        }
      }

      if (doPay) {
        (inv.payments || []).forEach(p => {
          const d = (p.date || (p.createdAt || '').slice(0, 10) || '');
          if (from && d && d < from) return;
          if (to && d && d > to) return;
          const mth = (p.method || '').toLowerCase();
          if (method && mth !== method) return;
          rows.push({
            kind: 'payment',
            id: p.id || (inv.id + '-pay'),
            date: d || '—',
            clientId: inv.clientId || '',
            clientName,
            ref: inv.invoiceNumber || '—',
            title: inv.title || '',
            method: p.method || '—',
            note: p.note || '',
            amount: Number(p.amount) || 0,
            editable: false
          });
        });
      }
    });
  }

  if (wantCustom) {
    ensureReportRows();
    (data.reportTableRows || []).forEach(r => {
      // Only filter by client when a client is set on the row
      if (clientSet && clientSet.size && r.clientId && !clientSet.has(r.clientId)) return;
      const d = (r.date || '').slice(0, 10);
      // Date filters: empty date still shows
      if (d && from && d < from) return;
      if (d && to && d > to) return;
      const client = r.clientId ? getClient(r.clientId) : null;
      const itemNote = (Array.isArray(r.items) && r.items.length)
        ? r.items.map(function (it) { return (it.name || '') + (it.qty > 1 ? ' ×' + it.qty : ''); }).filter(Boolean).join(', ')
        : (r.detail || '');
      rows.push({
        kind: 'custom',
        id: r.id,
        date: d || '—',
        clientId: r.clientId || '',
        clientName: client ? client.name : (r.clientName || '—'),
        ref: r.ref || '—',
        title: r.title || '',
        method: r.typeLabel || 'Custom',
        note: itemNote,
        amount: Number(r.amount) || 0,
        editable: true,
        invoiceId: r.invoiceId || null,
        itemCount: Array.isArray(r.items) ? r.items.length : 0
      });
    });
  }

  rows.sort((a, b) => String(b.date).localeCompare(String(a.date)) || String(b.ref).localeCompare(String(a.ref)));
  return rows;
}

// Back-compat alias
function collectPaymentTransactions(opts) {
  return collectLedgerRows({ ...opts, type: 'payments', clientIds: opts.clientId ? [opts.clientId] : (opts.clientIds || null) });
}

function reportSelectAllClients(on) {
  document.querySelectorAll('#report-client-list input[type=checkbox]').forEach(cb => {
    cb.checked = !!on;
    const row = cb.closest('.select-row');
    if (row) row.classList.toggle('is-selected', !!on);
  });
}

function getSelectedReportClientIds() {
  return [...document.querySelectorAll('#report-client-list input[type=checkbox]:checked')].map(cb => cb.value);
}

function getReportFilterState() {
  const hid = document.getElementById('report-product-id');
  const clientEl = document.getElementById('report-client');
  const clientId = clientEl ? (clientEl.value || '') : '';
  return {
    from: document.getElementById('report-date-from')?.value || '',
    to: document.getElementById('report-date-to')?.value || '',
    clientId: clientId,
    clientIds: clientId ? [clientId] : [],
    type: document.getElementById('report-type')?.value || 'all',
    productId: (hid && hid.value) || '',
    sort: document.getElementById('report-sort')?.value || 'date-desc'
  };
}

function saveReportFilters() {
  try {
    localStorage.setItem(REPORT_FILTERS_KEY, JSON.stringify(getReportFilterState()));
  } catch (e) {}
}

function loadReportFilters() {
  try {
    return JSON.parse(localStorage.getItem(REPORT_FILTERS_KEY) || 'null');
  } catch (e) { return null; }
}

/** Rank invoice status so paid / partial beat older proforma / draft copies */
function reportStatusRank(status) {
  const s = String(status || '').toLowerCase();
  if (s === 'paid') return 100;
  if (s === 'partial') return 80;
  if (s === 'sent' || s === 'unpaid') return 50;
  if (s === 'overdue') return 40;
  if (s === 'cancelled') return 0;
  if (s === 'draft') return 10;
  return 30;
}

function normalizeInvoiceRef(ref) {
  return String(ref || '').trim().toUpperCase().replace(/\s+/g, '');
}

/**
 * Prefer the latest meaningful version of each invoice.
 * Same invoice number (or same client + number) → keep highest status rank, then newest updatedAt.
 * Drops cancelled; drops draft/proforma when a stronger status exists for that ref.
 */
function getPreferredInvoices() {
  const map = new Map();
  (data.invoices || []).forEach(function (inv) {
    if (!inv || !inv.id) return;
    const st = String(inv.status || '').toLowerCase();
    if (st === 'cancelled') return;
    const ref = normalizeInvoiceRef(inv.invoiceNumber);
    const key = ref
      ? ('ref:' + (inv.clientId || '') + ':' + ref)
      : ('id:' + inv.id);
    const prev = map.get(key);
    if (!prev) {
      map.set(key, inv);
      return;
    }
    const rNew = reportStatusRank(inv.status);
    const rOld = reportStatusRank(prev.status);
    if (rNew > rOld) {
      map.set(key, inv);
      return;
    }
    if (rNew === rOld) {
      const tNew = inv.updatedAt || inv.createdAt || inv.date || '';
      const tOld = prev.updatedAt || prev.createdAt || prev.date || '';
      if (String(tNew) >= String(tOld)) map.set(key, inv);
    }
  });
  return Array.from(map.values());
}

function reportStatusBucket(status) {
  const s = String(status || '').toLowerCase();
  if (s === 'paid') return 'paid';
  if (s === 'partial') return 'partial';
  if (s === 'cancelled') return 'cancelled';
  if (s === 'draft') return 'draft';
  return 'unpaid'; // sent, unpaid, overdue, etc.
}

/**
 * Primary report rows: one line per product sold (invoice line),
 * plus services / expenses when type filter asks for them.
 */
function collectReportRows(filters) {
  filters = filters || getReportFilterState();
  const from = filters.from || '';
  const to = filters.to || '';
  const clientId = filters.clientId || '';
  const productId = filters.productId || '';
  const type = filters.type || 'all';
  const rows = [];

  const wantSales = type === 'all' || type === 'paid' || type === 'partial' || type === 'unpaid';
  const wantServices = type === 'all' || type === 'services';
  const wantExpenses = type === 'all' || type === 'expenses';

  if (wantSales) {
    getPreferredInvoices().forEach(function (inv) {
      const bucket = reportStatusBucket(inv.status);
      if (type === 'paid' && bucket !== 'paid') return;
      if (type === 'partial' && bucket !== 'partial') return;
      if (type === 'unpaid' && bucket !== 'unpaid') return;

      if (clientId && inv.clientId !== clientId) return;
      const d = (inv.date || (inv.createdAt || '').slice(0, 10) || '');
      if (from && d && d < from) return;
      if (to && d && d > to) return;

      const client = getClient(inv.clientId);
      const clientName = client ? client.name : (inv.clientName || '—');
      const items = inv.items || [];
      if (!items.length) {
        // Invoice with no lines — still show as one row if no product filter
        if (productId) return;
        rows.push({
          kind: 'sale',
          id: inv.id,
          date: d || '—',
          clientId: inv.clientId || '',
          clientName: clientName,
          productId: '',
          productName: inv.title || 'Invoice',
          sku: '',
          qty: 1,
          amount: Number(inv.totalNgn != null ? inv.totalNgn : inv.totalNGN) || 0,
          ref: inv.invoiceNumber || '—',
          status: bucket,
          statusRaw: inv.status || '',
          invoiceId: inv.id
        });
        return;
      }
      items.forEach(function (it, idx) {
        const pid = it.productId || '';
        const name = (it.name || '').trim() || 'Item';
        if (productId) {
          if (pid && pid !== productId) return;
          if (!pid) {
            const p = getProduct(productId);
            const matchName = p && p.name && name.toLowerCase() === String(p.name).toLowerCase();
            const matchSku = p && p.sku && name.toLowerCase().indexOf(String(p.sku).toLowerCase()) >= 0;
            if (!matchName && !matchSku) return;
          }
        }
        const qty = Number(it.qty) || 0;
        const line = Number(it.lineNgn != null ? it.lineNgn : it.lineNGN) ||
          (qty * (Number(it.unitNgn != null ? it.unitNgn : it.unitNGN) || 0));
        const p = pid ? getProduct(pid) : null;
        rows.push({
          kind: 'sale',
          id: inv.id + '-' + idx,
          date: d || '—',
          clientId: inv.clientId || '',
          clientName: clientName,
          productId: pid,
          productName: name || (p && p.name) || 'Item',
          sku: (p && p.sku) || it.sku || '',
          qty: qty,
          amount: line,
          ref: inv.invoiceNumber || '—',
          status: bucket,
          statusRaw: inv.status || '',
          invoiceId: inv.id
        });
      });
    });
  }

  if (wantServices) {
    (data.services || []).forEach(function (svc) {
      if (clientId && svc.clientId !== clientId) return;
      const d = (svc.date || (svc.createdAt || '').slice(0, 10) || '');
      if (from && d && d < from) return;
      if (to && d && d > to) return;
      if (productId) return; // product filter not applicable
      const client = svc.clientId ? getClient(svc.clientId) : null;
      rows.push({
        kind: 'service',
        id: svc.id || ('svc-' + d),
        date: d || '—',
        clientId: svc.clientId || '',
        clientName: client ? client.name : (svc.clientName || '—'),
        productId: '',
        productName: svc.title || svc.name || svc.description || 'Service',
        sku: '',
        qty: Number(svc.qty) || 1,
        amount: Number(svc.amount) || Number(svc.totalNgn) || 0,
        ref: svc.ref || svc.invoiceNumber || '—',
        status: 'service',
        statusRaw: 'service',
        invoiceId: ''
      });
    });
  }

  if (wantExpenses) {
    (data.officeExpenses || []).forEach(function (ex) {
      const d = (ex.date || (ex.createdAt || '').slice(0, 10) || '');
      if (from && d && d < from) return;
      if (to && d && d > to) return;
      if (clientId) return; // expenses are office-level
      if (productId) return;
      rows.push({
        kind: 'expense',
        id: ex.id || ('exp-' + d),
        date: d || '—',
        clientId: '',
        clientName: 'Office',
        productId: '',
        productName: ex.title || ex.name || ex.category || 'Expense',
        sku: '',
        qty: 1,
        amount: Number(ex.amount) || 0,
        ref: ex.ref || '—',
        status: 'expense',
        statusRaw: 'expense',
        invoiceId: ''
      });
    });
  }

  return sortReportRows(rows, filters.sort || 'date-desc');
}

function sortReportRows(rows, sort) {
  const list = rows.slice();
  const cmpStr = function (a, b) { return String(a || '').localeCompare(String(b || '')); };
  switch (sort) {
    case 'date-asc':
      list.sort(function (a, b) { return cmpStr(a.date, b.date) || cmpStr(a.clientName, b.clientName); });
      break;
    case 'amount-desc':
      list.sort(function (a, b) { return (b.amount || 0) - (a.amount || 0); });
      break;
    case 'amount-asc':
      list.sort(function (a, b) { return (a.amount || 0) - (b.amount || 0); });
      break;
    case 'name-asc':
      list.sort(function (a, b) { return cmpStr(a.clientName, b.clientName) || cmpStr(a.productName, b.productName); });
      break;
    case 'name-desc':
      list.sort(function (a, b) { return cmpStr(b.clientName, a.clientName) || cmpStr(b.productName, a.productName); });
      break;
    case 'qty-desc':
      list.sort(function (a, b) { return (b.qty || 0) - (a.qty || 0); });
      break;
    case 'qty-asc':
      list.sort(function (a, b) { return (a.qty || 0) - (b.qty || 0); });
      break;
    case 'date-desc':
    default:
      list.sort(function (a, b) { return cmpStr(b.date, a.date) || cmpStr(a.clientName, b.clientName); });
  }
  return list;
}

/** Back-compat helpers used elsewhere */
function collectProductSalesByClient(filters) {
  const rows = collectReportRows(Object.assign({}, filters || getReportFilterState(), { type: filters && filters.type ? filters.type : 'all' }));
  const byKey = {};
  rows.filter(function (r) { return r.kind === 'sale'; }).forEach(function (r) {
    const key = (r.clientId || r.clientName) + '|' + (r.productId || r.productName);
    if (!byKey[key]) {
      byKey[key] = {
        clientId: r.clientId,
        clientName: r.clientName,
        productId: r.productId,
        productName: r.productName,
        sku: r.sku,
        qty: 0,
        amount: 0
      };
    }
    byKey[key].qty += Number(r.qty) || 0;
    byKey[key].amount += Number(r.amount) || 0;
  });
  return Object.values(byKey).sort(function (a, b) {
    return a.clientName.localeCompare(b.clientName) || a.productName.localeCompare(b.productName);
  });
}

function collectLedgerRows(opts) {
  // Map old callers onto the new sale-line model
  const filters = Object.assign({}, getReportFilterState(), opts || {});
  if (opts && opts.clientIds && opts.clientIds.length === 1) filters.clientId = opts.clientIds[0];
  if (opts && opts.from) filters.from = opts.from;
  if (opts && opts.to) filters.to = opts.to;
  return collectReportRows(filters).map(function (r) {
    return {
      kind: r.kind === 'sale' ? 'invoice' : r.kind,
      id: r.id,
      date: r.date,
      clientId: r.clientId,
      clientName: r.clientName,
      ref: r.ref,
      title: r.productName,
      method: r.status,
      note: 'Qty ' + r.qty,
      amount: r.amount,
      editable: false
    };
  });
}

function getSelectedReportClientIds() {
  const id = document.getElementById('report-client')?.value || '';
  return id ? [id] : [];
}

function reportSelectAllClients() { /* no-op: dropdown mode */ }

function onReportProductSearchInput() {
  const input = document.getElementById('report-product-search');
  const drop = document.getElementById('report-product-drop');
  const hid = document.getElementById('report-product-id');
  if (!input || !drop) return;
  const q = String(input.value || '').trim().toLowerCase();
  if (!q) {
    if (hid) hid.value = '';
    drop.classList.add('hidden');
    drop.innerHTML = '';
    renderTransactionReport();
    return;
  }
  const matches = (data.products || []).filter(function (p) {
    const hay = ((p.sku || '') + ' ' + (p.name || '') + ' ' + (p.brand || '')).toLowerCase();
    return hay.indexOf(q) >= 0;
  }).slice(0, 40);
  if (!matches.length) {
    drop.innerHTML = '<div class="report-product-opt muted">No matches</div>';
    drop.classList.remove('hidden');
    return;
  }
  drop.innerHTML = matches.map(function (p) {
    const lab = (p.sku ? p.sku + ' · ' : '') + (p.name || p.id);
    return '<button type="button" class="report-product-opt" data-id="' + p.id + '">' + escHtml(lab) + '</button>';
  }).join('');
  drop.classList.remove('hidden');
  drop.querySelectorAll('.report-product-opt[data-id]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      const id = btn.getAttribute('data-id');
      const p = getProduct(id);
      if (hid) hid.value = id || '';
      if (input) input.value = p ? ((p.sku ? p.sku + ' · ' : '') + (p.name || '')) : '';
      drop.classList.add('hidden');
      drop.innerHTML = '';
      renderTransactionReport();
    });
  });
}

function clearReportProductFilter() {
  const input = document.getElementById('report-product-search');
  const hid = document.getElementById('report-product-id');
  const drop = document.getElementById('report-product-drop');
  if (input) input.value = '';
  if (hid) hid.value = '';
  if (drop) { drop.classList.add('hidden'); drop.innerHTML = ''; }
  renderTransactionReport();
}

function onReportTypeChange() {
  renderTransactionReport();
}

function statusPillClass(status) {
  const s = String(status || '').toLowerCase();
  if (s === 'paid') return 'report-status-pill is-paid';
  if (s === 'partial') return 'report-status-pill is-partial';
  if (s === 'service') return 'report-status-pill is-service';
  if (s === 'expense') return 'report-status-pill is-expense';
  return 'report-status-pill is-unpaid';
}

function statusLabel(status) {
  const s = String(status || '').toLowerCase();
  if (s === 'paid') return 'Paid';
  if (s === 'partial') return 'Partial';
  if (s === 'service') return 'Service';
  if (s === 'expense') return 'Expense';
  if (s === 'draft') return 'Draft';
  return 'Unpaid';
}

function initReportsPage() {
  const saved = loadReportFilters() || {};
  const clientSel = document.getElementById('report-client');
  const clients = (data.clients || []).slice().sort(function (a, b) {
    return (a.name || '').localeCompare(b.name || '');
  });
  if (clientSel) {
    clientSel.innerHTML = '<option value="">All clients</option>' + clients.map(function (c) {
      return '<option value="' + c.id + '">' + escHtml(c.name || 'Client') + '</option>';
    }).join('');
    if (saved.clientId) clientSel.value = saved.clientId;
  }

  const from = document.getElementById('report-date-from');
  const to = document.getElementById('report-date-to');
  if (from) {
    if (saved.from) from.value = saved.from;
    else {
      const now = new Date();
      from.value = localYMD(new Date(now.getFullYear(), now.getMonth(), 1));
    }
  }
  if (to) to.value = localYMD(new Date());
  const type = document.getElementById('report-type');
  if (type && saved.type) type.value = saved.type;
  else if (type) type.value = 'all';
  const sort = document.getElementById('report-sort');
  if (sort && saved.sort) sort.value = saved.sort;

  try {
    if (saved.productId) {
      const p = getProduct(saved.productId);
      const hid = document.getElementById('report-product-id');
      const inp = document.getElementById('report-product-search');
      if (hid) hid.value = saved.productId;
      if (inp && p) inp.value = (p.sku ? p.sku + ' · ' : '') + (p.name || '');
    }
  } catch (e) {}

  renderTransactionReport();
}

function renderTransactionReport() {
  const toEl = document.getElementById('report-date-to');
  if (toEl && !toEl.value) toEl.value = localYMD(new Date());
  const filters = getReportFilterState();
  saveReportFilters();
  const rows = collectReportRows(filters);
  const summary = document.getElementById('report-summary');
  const preview = document.getElementById('report-preview');
  if (!preview) return;

  const totalValue = rows.reduce(function (s, r) { return s + (Number(r.amount) || 0); }, 0);
  const totalQty = rows.reduce(function (s, r) { return s + (Number(r.qty) || 0); }, 0);
  const clientCount = new Set(rows.map(function (r) { return r.clientId || r.clientName; })).size;
  const paidValue = rows.filter(function (r) { return r.status === 'paid'; })
    .reduce(function (s, r) { return s + (Number(r.amount) || 0); }, 0);

  if (summary) {
    summary.innerHTML =
      '<div class="report-stat"><p class="rsl">Lines</p><p class="rsv">' + rows.length + '</p></div>' +
      '<div class="report-stat"><p class="rsl">Units</p><p class="rsv">' + totalQty + '</p></div>' +
      '<div class="report-stat"><p class="rsl">Total value</p><p class="rsv">' + formatNGN(totalValue) + '</p></div>' +
      '<div class="report-stat"><p class="rsl">Paid value</p><p class="rsv">' + formatNGN(paidValue) + '</p></div>' +
      '<div class="report-stat"><p class="rsl">Clients</p><p class="rsv">' + clientCount + '</p></div>';
  }

  if (!rows.length) {
    preview.innerHTML = '<div class="panel-soft report-empty">No sales match these filters. Adjust date, client, product, or type.</div>';
    return;
  }

  // Desktop table
  const tableRows = rows.map(function (r) {
    return '<tr>' +
      '<td>' + escHtml(r.date) + '</td>' +
      '<td>' + escHtml(r.clientName) + '</td>' +
      '<td>' + escHtml(r.productName) + (r.sku ? '<div class="text-xs text-slate-400">' + escHtml(r.sku) + '</div>' : '') + '</td>' +
      '<td class="num">' + (r.qty || 0) + '</td>' +
      '<td class="num">' + formatNGN(r.amount) + '</td>' +
      '<td>' + escHtml(r.ref) + '</td>' +
      '<td><span class="' + statusPillClass(r.status) + '">' + statusLabel(r.status) + '</span></td>' +
      '</tr>';
  }).join('');

  // Mobile cards — amount purchased is prominent
  const cards = rows.map(function (r) {
    return '<div class="entity-card report-result-card report-card-spaced">' +
      '<div class="entity-card-header">' +
        '<div class="entity-card-main">' +
          '<span class="entity-card-title">' + escHtml(r.clientName) + '</span>' +
          '<span class="entity-card-sub">' + escHtml(r.date) + ' · ' + escHtml(r.ref) + '</span>' +
        '</div>' +
        '<span class="entity-card-price">' + formatNGN(r.amount) + '</span>' +
      '</div>' +
      '<div class="entity-card-body is-open" style="display:block">' +
        '<div class="entity-detail"><span class="entity-detail-label">Product</span><span class="entity-detail-value">' + escHtml(r.productName) + '</span></div>' +
        '<div class="entity-detail"><span class="entity-detail-label">Qty</span><span class="entity-detail-value">' + (r.qty || 0) + '</span></div>' +
        '<div class="entity-detail"><span class="entity-detail-label">Amount</span><span class="entity-detail-value">' + formatNGN(r.amount) + '</span></div>' +
        '<div class="entity-detail"><span class="entity-detail-label">Status</span><span class="entity-detail-value"><span class="' + statusPillClass(r.status) + '">' + statusLabel(r.status) + '</span></span></div>' +
      '</div></div>';
  }).join('');

  preview.innerHTML =
    '<div class="responsive-table-shell panel-soft">' +
      '<div class="table-desktop-only"><div class="rt-scroll">' +
        '<table class="report-table data-table">' +
          '<thead><tr>' +
            '<th>Date</th><th>Client</th><th>Product</th><th class="num">Qty</th><th class="num">Amount</th><th>Invoice ref</th><th>Status</th>' +
          '</tr></thead>' +
          '<tbody>' + tableRows + '</tbody>' +
          '<tfoot><tr><td colspan="3" class="num" style="font-weight:700">Total</td>' +
            '<td class="num" style="font-weight:700">' + totalQty + '</td>' +
            '<td class="num" style="font-weight:800">' + formatNGN(totalValue) + '</td>' +
            '<td colspan="2"></td></tr></tfoot>' +
        '</table></div></div>' +
      '<div class="table-mobile-only entity-cards report-mobile-cards">' + cards + '</div>' +
    '</div>';
}

function printTransactionReport() {
  try {
    ensureBackupBeforeSensitiveAction('printing this report');
    const filters = getReportFilterState();
    const rows = collectReportRows(filters);
    const co = data.company || {};
    const clientLabel = filters.clientId
      ? ((getClient(filters.clientId) || {}).name || 'Client')
      : 'All clients';
    const period = (filters.from || '…') + ' → ' + (filters.to || '…');
    const productLabel = filters.productId
      ? ((getProduct(filters.productId) || {}).name || filters.productId)
      : 'All products';
    const typeLabel = ({
      all: 'All statuses', paid: 'Paid', partial: 'Partial', unpaid: 'Unpaid',
      services: 'Services', expenses: 'Expenses'
    })[filters.type] || filters.type;

    const totalValue = rows.reduce(function (s, r) { return s + (Number(r.amount) || 0); }, 0);
    const totalQty = rows.reduce(function (s, r) { return s + (Number(r.qty) || 0); }, 0);

    function sanitize(s, max) {
      return String(s || '').replace(/[\\/:*?"<>|]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max || 40);
    }

    if (typeof loadJsPdf !== 'function') {
      alert('PDF engine not available.');
      return;
    }

    loadJsPdf().then(function (JsPDF) {
      const doc = new JsPDF({ unit: 'pt', format: 'a4' });
      const W = doc.internal.pageSize.getWidth();
      const H = doc.internal.pageSize.getHeight();
      const M = 40;
      const TEAL = [15, 118, 110];
      const GRAY = [100, 116, 139];
      const INK = [30, 41, 59];
      let y = 48;

      try {
        const logo = (typeof COMPANY_LOGO_DATAURL !== 'undefined') ? COMPANY_LOGO_DATAURL : null;
        if (logo) {
          const fmt = logo.indexOf('image/jpeg') >= 0 ? 'JPEG' : 'PNG';
          doc.addImage(logo, fmt, M, y - 8, 150, 30);
        }
      } catch (eL) {}

      doc.setFont('helvetica', 'bold');
      doc.setFontSize(15);
      doc.setTextColor.apply(doc, TEAL);
      doc.text('SALES REPORT', W - M, y + 4, { align: 'right' });
      y += 18;
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(9);
      doc.setTextColor.apply(doc, GRAY);
      doc.text('Period: ' + period, W - M, y, { align: 'right' }); y += 11;
      doc.text('Client: ' + clientLabel, W - M, y, { align: 'right' }); y += 11;
      doc.text('Product: ' + productLabel + '  ·  Type: ' + typeLabel, W - M, y, { align: 'right' }); y += 14;
      doc.setDrawColor.apply(doc, TEAL);
      doc.setLineWidth(2);
      doc.line(M, y, W - M, y);
      y += 16;

      doc.setFont('helvetica', 'bold');
      doc.setFontSize(10);
      doc.setTextColor.apply(doc, TEAL);
      doc.text(co.name || 'Medicano Resources Limited', M, y);
      y += 18;

      // Column headers
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(8);
      doc.setTextColor.apply(doc, TEAL);
      const cDate = M;
      const cClient = M + 58;
      const cProduct = M + 148;
      const cQty = W - M - 150;
      const cAmt = W - M - 95;
      const cRef = W - M - 55;
      // Use simpler fixed columns
      doc.text('Date', M, y);
      doc.text('Client', M + 52, y);
      doc.text('Product', M + 130, y);
      doc.text('Qty', W - M - 155, y, { align: 'right' });
      doc.text('Amount', W - M - 90, y, { align: 'right' });
      doc.text('Ref', W - M - 55, y);
      doc.text('Status', W - M, y, { align: 'right' });
      y += 6;
      doc.setDrawColor(226, 232, 240);
      doc.setLineWidth(0.6);
      doc.line(M, y, W - M, y);
      y += 11;

      doc.setFont('helvetica', 'normal');
      doc.setFontSize(8);
      doc.setTextColor.apply(doc, INK);

      rows.forEach(function (r) {
        if (y > H - 56) {
          doc.addPage();
          y = 48;
          doc.setFont('helvetica', 'bold');
          doc.setFontSize(8);
          doc.setTextColor.apply(doc, TEAL);
          doc.text('Date', M, y);
          doc.text('Client', M + 52, y);
          doc.text('Product', M + 130, y);
          doc.text('Qty', W - M - 155, y, { align: 'right' });
          doc.text('Amount', W - M - 90, y, { align: 'right' });
          doc.text('Ref', W - M - 55, y);
          doc.text('Status', W - M, y, { align: 'right' });
          y += 6;
          doc.setDrawColor(226, 232, 240);
          doc.line(M, y, W - M, y);
          y += 11;
          doc.setFont('helvetica', 'normal');
          doc.setFontSize(8);
          doc.setTextColor.apply(doc, INK);
        }
        doc.text(String(r.date || '—').slice(0, 10), M, y);
        doc.text(String(r.clientName || '—').slice(0, 14), M + 52, y);
        doc.text(String(r.productName || '—').slice(0, 28), M + 130, y);
        doc.text(String(r.qty || 0), W - M - 155, y, { align: 'right' });
        doc.text((Number(r.amount) || 0).toLocaleString('en-NG', { minimumFractionDigits: 2 }), W - M - 90, y, { align: 'right' });
        doc.text(String(r.ref || '—').slice(0, 10), W - M - 55, y);
        doc.text(statusLabel(r.status), W - M, y, { align: 'right' });
        y += 12;
      });

      if (!rows.length) {
        doc.text('No sales match these filters.', M, y);
        y += 14;
      }

      y += 10;
      doc.setDrawColor(226, 232, 240);
      doc.line(M, y, W - M, y);
      y += 14;
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(10);
      doc.setTextColor.apply(doc, TEAL);
      doc.text('Total qty: ' + totalQty, M, y);
      doc.text('Total value: ₦' + totalValue.toLocaleString('en-NG', { minimumFractionDigits: 2 }), W - M, y, { align: 'right' });

      const clientPart = sanitize(clientLabel, 40);
      const periodPart = sanitize((filters.from || 'all') + ' to ' + (filters.to || 'all'), 40);
      doc.save(clientPart + ' - Report - ' + periodPart + '.pdf');
    }).catch(function (err) {
      console.error(err);
      alert(err.message || 'Could not generate report PDF.');
    });
  } catch (err) {
    console.error('printTransactionReport', err);
    alert('Could not generate report PDF: ' + (err && err.message ? err.message : err));
  }
}

function exportTransactionReportCsv() {
  ensureBackupBeforeSensitiveAction('exporting this CSV');
  const filters = getReportFilterState();
  const rows = collectReportRows(filters);
  const lines = [['Date', 'Client', 'Product', 'SKU', 'Qty', 'Amount NGN', 'Invoice ref', 'Status']];
  rows.forEach(function (r) {
    lines.push([
      r.date,
      r.clientName,
      r.productName,
      r.sku || '',
      r.qty,
      (Number(r.amount) || 0).toFixed(2),
      r.ref,
      statusLabel(r.status)
    ]);
  });
  const totalValue = rows.reduce(function (s, r) { return s + (Number(r.amount) || 0); }, 0);
  const totalQty = rows.reduce(function (s, r) { return s + (Number(r.qty) || 0); }, 0);
  lines.push([]);
  lines.push(['TOTAL', '', '', '', totalQty, totalValue.toFixed(2), '', '']);
  const escape = function (v) {
    const s = String(v ?? '');
    if (/[",\n\r]/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
    return s;
  };
  const csv = lines.map(function (row) { return row.map(escape).join(','); }).join(String.fromCharCode(10));
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  const sanitize = function (s, max) {
    return String(s || '').replace(/[\\/:*?"<>|]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max || 40);
  };
  const clientPart = filters.clientId
    ? sanitize((getClient(filters.clientId) || {}).name || 'Client', 40)
    : 'All clients';
  const period = sanitize((filters.from || 'all') + ' to ' + (filters.to || 'all'), 40);
  a.download = clientPart + ' - Report - ' + period + '.csv';
  a.click();
  URL.revokeObjectURL(a.href);
}


function promptAddPayment(invId) {
  const inv = (data.invoices || []).find(x => x.id === invId);
  if (!inv) return;
  const bal = invoiceBalance(inv);
  const amount = prompt('Payment amount (NGN). Balance: ' + formatNGN(bal), String(Math.round(bal)));
  if (amount == null) return;
  const method = prompt('Method (transfer / cash / cheque / other)', 'transfer') || 'transfer';
  const note = prompt('Note (optional)', '') || '';
  addInvoicePayment(invId, amount, method, note);
  renderInvoices();
  if (currentInvoiceId === invId) renderInvoicePaymentsPanel();
  renderDashboard();
}

function renderInvoicePaymentsPanel() {
  const panel = document.getElementById('inv-payments-panel');
  if (!panel) return;
  const inv = currentInvoiceId ? (data.invoices || []).find(x => x.id === currentInvoiceId) : null;
  if (!inv) {
    panel.innerHTML = '<h4 class="font-semibold text-slate-800 mb-1">Payment tracking</h4><p class="text-sm text-slate-400">Save the invoice first, then record payments here.</p>';
    return;
  }
  const paid = invoicePaidTotal(inv);
  const bal = invoiceBalance(inv);
  const rows = (inv.payments || []).slice().sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  panel.innerHTML = `
    <div class="pay-panel-head">
      <h4 class="font-semibold text-slate-800 text-base">Payment tracking</h4>
      <p class="text-xs text-slate-500 mt-0.5">Partial payments update status automatically</p>
    </div>
    <div class="pay-summary">
      <div class="pay-summary-item"><span class="pay-summary-label">Total</span><span class="pay-summary-value">${formatNGN(inv.totalNgn || 0)}</span></div>
      <div class="pay-summary-item"><span class="pay-summary-label">Paid</span><span class="pay-summary-value text-emerald-700">${formatNGN(paid)}</span></div>
      <div class="pay-summary-item"><span class="pay-summary-label">Balance</span><span class="pay-summary-value text-rose-700">${formatNGN(bal)}</span></div>
    </div>
    <div class="pay-form-grid">
      <div class="pay-field">
        <label class="pay-label">Amount (NGN)</label>
        <input id="pay-amount" type="number" min="0" step="0.01" placeholder="0.00" class="pay-input" />
      </div>
      <div class="pay-field">
        <label class="pay-label">Method</label>
        <select id="pay-method" class="pay-input">
          <option value="transfer">Transfer</option>
          <option value="cash">Cash</option>
          <option value="cheque">Cheque</option>
          <option value="other">Other</option>
        </select>
      </div>
      <div class="pay-field">
        <label class="pay-label">Date</label>
        <input id="pay-date" type="date" class="pay-input" />
      </div>
      <div class="pay-field pay-field-note">
        <label class="pay-label">Note</label>
        <input id="pay-note" type="text" placeholder="Optional note" class="pay-input" />
      </div>
      <div class="pay-field pay-field-btn">
        <label class="pay-label">&nbsp;</label>
        <button type="button" class="pay-add-btn" onclick="submitInvoicePayment()">Add payment</button>
      </div>
    </div>
    <div class="pay-list">
      ${rows.length ? rows.map(p => `<div class="pay-list-row">
        <div class="pay-list-main">
          <span class="pay-list-amount">${formatNGN(p.amount)}</span>
          <span class="pay-list-meta">${escHtml((p.method || '').toUpperCase())} · ${escHtml(p.date || '')}</span>
          ${p.note ? `<span class="pay-list-note">${escHtml(p.note)}</span>` : ''}
        </div>
        <button type="button" class="pay-list-remove" onclick="removeInvoicePayment('${inv.id}','${p.id}'); renderInvoicePaymentsPanel(); renderInvoices();" aria-label="Remove">✕</button>
      </div>`).join('') : '<p class="text-slate-400 text-sm">No payments recorded yet.</p>'}
    </div>`;
  const d = document.getElementById('pay-date');
  if (d && !d.value) d.value = new Date().toISOString().slice(0, 10);
}

function submitInvoicePayment() {
  if (!currentInvoiceId) { alert('Save the invoice first.'); return; }
  const amount = document.getElementById('pay-amount')?.value;
  const method = document.getElementById('pay-method')?.value || 'transfer';
  const note = document.getElementById('pay-note')?.value || '';
  const date = document.getElementById('pay-date')?.value || '';
  addInvoicePayment(currentInvoiceId, amount, method, note, date);
  renderInvoicePaymentsPanel();
  renderInvoices();
  renderDashboard();
}

function saveNumberingSettings() {
  if (!data.numbering) data.numbering = {};
  data.numbering.quotePrefix = document.getElementById('set-quote-prefix')?.value || 'MQ-';
  data.numbering.invoicePrefix = document.getElementById('set-invoice-prefix')?.value || 'INV-';
  const nq = parseInt(document.getElementById('set-next-quote')?.value, 10);
  const ni = parseInt(document.getElementById('set-next-invoice')?.value, 10);
  if (!isNaN(nq)) { data.numbering.nextQuoteNum = nq; data.nextQuoteNum = nq; }
  if (!isNaN(ni)) { data.numbering.nextInvoiceNum = ni; data.nextInvoiceNum = ni; }
  data.settings = data.settings || {};
  data.settings.followUpDays = parseInt(document.getElementById('set-followup-days')?.value, 10) || 14;
  data.settings.autoDeductStockOnPaid = !!document.getElementById('set-auto-stock')?.checked;
  // device profile kept for audit trail only; username is under User settings
  saveData();
  logAudit('settings', 'Numbering / workflow settings saved');
  alert('Settings saved.');
}

function renderNoteTemplatesEditor() {
  const el = document.getElementById('note-templates-editor');
  if (!el) return;
  const list = data.noteTemplates || [];
  el.innerHTML = list.map(t => `
    <div class="settings-term-row" data-id="${t.id}">
      <input class="settings-input nt-name" value="${escHtml(t.name)}" placeholder="Template name" />
      <textarea class="settings-input nt-body" rows="2" placeholder="Body">${escHtml(t.body)}</textarea>
      <button type="button" class="btn-soft" onclick="this.closest('[data-id]').remove()">Remove</button>
    </div>`).join('') || '<p class="settings-help">No templates yet.</p>';
}

function saveNoteTemplates() {
  const rows = document.querySelectorAll('#note-templates-editor [data-id]');
  data.noteTemplates = [...rows].map(row => ({
    id: row.getAttribute('data-id') || uid(),
    name: row.querySelector('.nt-name')?.value.trim() || 'Template',
    body: row.querySelector('.nt-body')?.value.trim() || ''
  })).filter(t => t.body);
  saveData();
  logAudit('templates', 'Note templates saved');
  alert('Templates saved.');
  populateTemplateSelects();
}

function addNoteTemplateRow() {
  if (!data.noteTemplates) data.noteTemplates = [];
  data.noteTemplates.push({ id: uid(), name: 'New template', body: '' });
  renderNoteTemplatesEditor();
}

function populateTemplateSelects() {
  const opts = '<option value="">Insert template…</option>' +
    (data.noteTemplates || []).map(t => `<option value="${t.id}">${escHtml(t.name)}</option>`).join('');
  ['quote-template-select', 'inv-template-select'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.innerHTML = opts;
  });
}

function renderAuditLog() {
  const el = document.getElementById('audit-log-list');
  if (!el) return;
  const log = (data.auditLog || []).slice(0, 80);
  if (!log.length) { el.innerHTML = '<p class="text-slate-400 text-sm">No activity yet.</p>'; return; }
  el.innerHTML = log.map(a => `
    <div class="audit-row">
      <span class="audit-time">${escHtml((a.at || '').replace('T', ' ').slice(0, 19))}</span>
      <span class="audit-action">${escHtml(a.action)}</span>
      <span class="audit-detail">${escHtml(a.detail || '')}</span>
      <span class="audit-device">${escHtml(a.device || '')}</span>
    </div>`).join('');
}

// jsPDF quote PDF (aligned with invoice layout)
function generateQuotePdf(q) {
  const co = data.company || {};
  const client = getClient(q.clientId);
  const logo = (typeof COMPANY_LOGO_DATAURL !== 'undefined') ? COMPANY_LOGO_DATAURL : null;
  const items = q.items || [];
  const subtotal = q.subtotalNGN != null ? q.subtotalNGN : items.reduce((s, it) => s + (it.lineNGN || it.lineNgn || 0), 0);
  let discountAmt = (q.discountAmount != null && q.discountAmount !== '') ? Number(q.discountAmount) : NaN;
  let discount = Number(q.discount) || 0;
  if (isNaN(discountAmt) || discountAmt < 0) {
    discountAmt = subtotal * (discount / 100);
  } else if (subtotal > 0 && !discount) {
    discount = (discountAmt / subtotal) * 100;
  }
  discountAmt = Math.max(0, Math.min(discountAmt, subtotal));
  const total = q.totalNGN != null ? q.totalNGN : Math.max(0, subtotal - discountAmt);

  loadJsPdf().then(JsPDF => {
    const doc = new JsPDF({ unit: 'pt', format: 'a4' });
    const W = doc.internal.pageSize.getWidth();
    const H = doc.internal.pageSize.getHeight();
    const M = 42;
    const TEAL = [15, 118, 110];
    const GRAY = [100, 116, 139];
    const INK = [30, 41, 59];
    const LINE = [226, 232, 240];
    let y = 36;
    try {
      if (logo) {
        const fmt = logo.indexOf('image/jpeg') >= 0 ? 'JPEG' : 'PNG';
        doc.addImage(logo, fmt, M, y, 200, 40);
      }
    } catch (e) {}
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(20);
    doc.setTextColor(...TEAL);
    doc.text('QUOTATION', W - M, y + 14, { align: 'right' });
    doc.setFontSize(11);
    doc.setTextColor(...INK);
    doc.text(String(q.quoteNumber || 'DRAFT'), W - M, y + 30, { align: 'right' });
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(...GRAY);
    doc.text('Date: ' + new Date(q.createdAt || Date.now()).toLocaleDateString(), W - M, y + 44, { align: 'right' });
    if (q.validUntil) doc.text('Valid until: ' + q.validUntil, W - M, y + 56, { align: 'right' });
    y = 100;
    doc.setDrawColor(...TEAL);
    doc.setLineWidth(2);
    doc.line(M, y, W - M, y);
    y += 20;
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(12);
    doc.setTextColor(...TEAL);
    doc.text(co.name || 'Medicano Resources Limited', M, y);
    y += 14;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(...GRAY);
    if (co.address) { doc.splitTextToSize(co.address, W * 0.65).forEach(ln => { doc.text(ln, M, y); y += 11; }); }
    y += 8;
    doc.setFontSize(9);
    doc.text('BILL TO', M, y); y += 12;
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(12);
    doc.setTextColor(...INK);
    doc.text(client ? client.name : '—', M, y); y += 14;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(10);
    doc.setTextColor(...GRAY);
    if (client && client.contact) { doc.text('Attn: ' + client.contact, M, y); y += 12; }
    if (client && client.address) { doc.text(String(client.address), M, y); y += 12; }
    y += 6;
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(...INK);
    doc.text('Project: ' + (q.title || ''), M, y); y += 16;

    const colDesc = M, colAmount = W - M, colQty = W - M - 90, colUnit = W - M - 170;
    const descMaxW = colUnit - colDesc - 20;
    doc.setDrawColor(...LINE);
    doc.line(M, y, W - M, y); y += 12;
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9);
    doc.setTextColor(...TEAL);
    doc.text('Description', colDesc, y);
    doc.text('Unit Price', colUnit, y, { align: 'right' });
    doc.text('Qty', colQty, y, { align: 'right' });
    doc.text('Amount', colAmount, y, { align: 'right' });
    y += 6; doc.setDrawColor(...LINE); doc.line(M, y, W - M, y); y += 14;

    items.forEach(it => {
      if (y > H - 100) { doc.addPage(); y = 50; }
      const name = it.name || 'Item';
      const qty = Number(it.qty) || 0;
      const unit = Number(it.unitNGN != null ? it.unitNGN : it.unitNgn) || 0;
      const line = Number(it.lineNGN != null ? it.lineNGN : it.lineNgn) || (qty * unit);
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(10);
      doc.setTextColor(...INK);
      const nl = doc.splitTextToSize(String(name), descMaxW);
      doc.text(nl[0] || '', colDesc, y);
      doc.setFont('helvetica', 'normal');
      doc.text(formatNairaPlain(unit), colUnit, y, { align: 'right' });
      doc.text(String(qty), colQty, y, { align: 'right' });
      doc.setFont('helvetica', 'bold');
      doc.text(formatNairaPlain(line), colAmount, y, { align: 'right' });
      y += 16;
      doc.setDrawColor(...LINE);
      doc.setLineWidth(0.4);
      doc.line(M, y - 4, W - M, y - 4);
    });

    y += 12;
    const totalsRight = colAmount;
    const drawQTotal = (label, value, yPos, bold) => {
      const amountStr = formatNairaPlain(value);
      doc.setFont('helvetica', bold ? 'bold' : 'normal');
      doc.setFontSize(bold ? 13 : 11);
      doc.setTextColor(...(bold ? TEAL : INK));
      doc.text(amountStr, totalsRight, yPos, { align: 'right' });
      const amountW = doc.getTextWidth(amountStr);
      doc.text(label, totalsRight - amountW - 14, yPos, { align: 'right' });
      return totalsRight - amountW - 14 - doc.getTextWidth(label);
    };
    const qLeft = drawQTotal('Subtotal', subtotal, y, false);
    if (discount > 0) {
      y += 14;
      drawQTotal('Discount (' + discount + '%)', -(subtotal * discount / 100), y, false);
    }
    y += 8;
    doc.setDrawColor(...TEAL);
    doc.setLineWidth(1.2);
    doc.line(Math.min(qLeft, totalsRight - 120), y, totalsRight, y);
    y += 16;
    drawQTotal('TOTAL', total, y, true);
    y += 28;
    if (q.notes) {
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(9);
      doc.setTextColor(...GRAY);
      doc.text('NOTES', M, y); y += 12;
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(...INK);
      doc.splitTextToSize(String(q.notes), W - 2 * M).forEach(ln => { doc.text(ln, M, y); y += 11; });
      y += 10;
    }
    // Signature block
    if (y > H - 90) { doc.addPage(); y = 50; }
    doc.setDrawColor(...LINE);
    doc.line(M, y + 40, M + 180, y + 40);
    doc.line(W - M - 180, y + 40, W - M, y + 40);
    doc.setFontSize(8);
    doc.setTextColor(...GRAY);
    doc.text('Prepared by / Signature', M, y + 52);
    doc.text('Client acknowledgement', W - M - 180, y + 52);

    const safe = (s) => String(s || 'Quote').replace(/[\\/:*?"<>|]/g, ' ').trim().slice(0, 40);
    if (typeof drawPdfSignatureBlock === 'function') {
      y += 16;
      y = drawPdfSignatureBlock(doc, M, W, y);
    }
    doc.save(safe(client && client.name) + ' - ' + safe(q.quoteNumber) + '.pdf');
  }).catch(err => alert(err.message || 'Could not generate quote PDF'));
}

function printQuoteById(id) {
  const q = (data.quotes || []).find(x => x.id === id);
  if (!q) { alert('Quote not found'); return; }
  generateQuotePdf(q);
}

// -------------------- Init --------------------
document.addEventListener('DOMContentLoaded', () => {
  loadData();
  updateRatesDisplay();
  initDarkMode();

  // Sidebar links
  document.querySelectorAll('.sidebar-link').forEach(a => {
    a.addEventListener('click', (e) => {
      e.preventDefault();
      navigate(a.dataset.page);
    });
  });

  // Mobile menu
  document.getElementById('menu-btn').addEventListener('click', () => {
    const sb = document.getElementById('sidebar');
    const overlay = document.getElementById('sidebar-overlay');
    const isOpen = !sb.classList.contains('-translate-x-full');
    if (isOpen) {
      closeSidebar();
    } else {
      sb.classList.remove('-translate-x-full');
      sb.classList.add('translate-x-0');
      if (overlay) overlay.classList.remove('hidden');
    }
  });

  // Search listeners
  (function () {
    let t;
    document.getElementById('product-search')?.addEventListener('input', function () {
      window._productPage = 1;
      clearTimeout(t);
      t = setTimeout(renderProducts, 200);
    });
  })();
  document.getElementById('product-category-filter')?.addEventListener('change', function(){ window._productPage = 1; renderProducts(); });
  document.getElementById('quote-status-filter')?.addEventListener('change', renderQuotes);
  document.getElementById('quote-date-from')?.addEventListener('change', renderQuotes);
  document.getElementById('quote-date-to')?.addEventListener('change', renderQuotes);
  document.getElementById('invoice-date-from')?.addEventListener('change', renderInvoices);
  document.getElementById('invoice-date-to')?.addEventListener('change', renderInvoices);
  document.getElementById('global-search')?.addEventListener('input', (e) => runGlobalSearch(e.target.value));
  document.getElementById('global-search')?.addEventListener('focus', (e) => runGlobalSearch(e.target.value));
  document.addEventListener('click', (e) => {
    const box = document.getElementById('global-search-results');
    const input = document.getElementById('global-search');
    if (box && input && !box.contains(e.target) && e.target !== input) box.classList.add('hidden');
  });


  // Close modals on backdrop click
  ['modal-product', 'modal-client'].forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    el.addEventListener('click', (e) => {
      if (e.target.id === id) closeModal(id);
    });
  });

  let startPage = 'dashboard';
  try {
    const saved = sessionStorage.getItem('medicano_last_page');
    // Don't restore editor pages on cold start (empty forms / confusing)
    const skipRestore = ['product-editor', 'quote-editor', 'invoice-editor', 'client-detail'];
    if (saved && document.getElementById('page-' + saved) && skipRestore.indexOf(saved) === -1) {
      startPage = saved;
    }
  } catch (e) {}
  // Always hydrate dashboard stats first so numbers are never stuck at zero
  try { renderDashboard(); } catch (e) { console.error(e); }
  navigate(startPage);
  try { updateConnectionBadge(); } catch (e) {}
  window.addEventListener('online', updateConnectionBadge);
  window.addEventListener('offline', updateConnectionBadge);
  try { window.scrollTo(0, 0); } catch (e) {}
});

window.onMedicanoAuthChanged = function () {
  try { updateConnectionBadge(); } catch (e) {}
  try { updateDashboardGreeting(); } catch (e) {}
};

function closeSidebar() {
  const sb = document.getElementById('sidebar');
  const overlay = document.getElementById('sidebar-overlay');
  if (sb) {
    sb.classList.add('-translate-x-full');
    sb.classList.remove('translate-x-0');
  }
  if (overlay) overlay.classList.add('hidden');
}

